import {
  Component,
  OnInit,
  ChangeDetectionStrategy,
  Input,
  Output,
  EventEmitter,
  ChangeDetectorRef
} from '@angular/core';
import { DestroySubject, getRandomFromArray } from '@honoregaming/core';
import { BettingApiService } from '@honoregaming/betslip';
import { takeUntil } from 'rxjs/operators';
import { timer } from 'rxjs';
import { InstantGameMode, InstantGameName, InstantGameState } from '@honoregaming/types';
import { MusikaStatus } from '../../../enums/musika.enum';
import { musikaInstruments } from '../../../constants/musika-instruments';

@Component({
  selector: 'hg-musika-popin',
  templateUrl: './musika-popin.component.html',
  styleUrls: ['./musika-popin.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class MusikaPopinComponent extends DestroySubject implements OnInit {
  @Input() wonInstrument: { path: string; id: number };
  @Input() payableAmount: number;
  @Input() step: number;
  @Input() transactionId: number;
  @Input() stake: number;

  @Output() close = new EventEmitter<'won' | 'won-demo' | 'won-doq' | 'lost'>();

  doubleOrQuitChoices: { path: string; id: number }[];
  doubleOrQuitChosen: { path: string; id: number };
  isWinner: boolean;
  autoCloseDelay: number = 180000;

  MusikaStatus = MusikaStatus;

  constructor(private bettingApiService: BettingApiService, private cdRef: ChangeDetectorRef) {
    super();
  }

  ngOnInit(): void {
    if (this.step === MusikaStatus.WonSpin) {
      this.startTimer();
    }
    if (this.step === MusikaStatus.LostSpin) {
      this.closePopupWithDelay(100000, 'lost');
    }
    if (this.step === MusikaStatus.WonDemo) {
      this.closePopupWithDelay(2000, 'won-demo');
    }
  }

  startTimer() {
    timer(0, 1000)
      .pipe(takeUntil(this.destroy$))
      .subscribe(_ => {
        if (this.autoCloseDelay > 0) {
          this.autoCloseDelay = this.autoCloseDelay - 1000;
        } else {
          this.keepYourGains();
        }
        this.cdRef.markForCheck();
      });
  }

  keepYourGains() {
    this.updateMusikaInstantGameTransaction(false).subscribe(_ => this.closePopup('won'));
  }

  closePopup(status: 'won' | 'won-demo' | 'won-doq' | 'lost') {
    this.close.next(status);
  }

  closePopupWithDelay(delay: number, status: 'won' | 'won-demo' | 'won-doq' | 'lost') {
    setTimeout(() => {
      this.close.next(status);
    }, delay);
  }

  playDoubleOrQuit() {
    do {
      this.doubleOrQuitChoices = [getRandomFromArray(musikaInstruments), getRandomFromArray(musikaInstruments)];
    } while (this.doubleOrQuitChoices[0].id === this.doubleOrQuitChoices[1].id);
    this.step = MusikaStatus.ChooseItem;
  }

  coinFlip(index: number) {
    this.step = MusikaStatus.Loading;
    this.doubleOrQuitChosen = this.doubleOrQuitChoices[index];
    this.updateMusikaInstantGameTransaction(true).subscribe(r => {
      this.isWinner = r.instantGameTransaction.state === InstantGameState.Won;
      this.step = this.isWinner ? MusikaStatus.Result : MusikaStatus.LostSpin;
      this.closePopupWithDelay(2500, this.isWinner ? 'won-doq' : 'lost');
    });
  }

  updateMusikaInstantGameTransaction(doubleOrQuit: boolean) {
    const selection = {};
    return this.bettingApiService.updateMusikaInstantGameTransaction({
      id: this.transactionId,
      instantGameName: InstantGameName.Musika,
      stake: this.stake,
      selection,
      instantGameMode: InstantGameMode.Real,
      doubleOrQuit: doubleOrQuit
    });
  }
}
