import { Component, OnInit, ChangeDetectionStrategy, Optional, Input, ChangeDetectorRef } from '@angular/core';
import { Router } from '@angular/router';
import { Observable } from 'rxjs';
import { shareReplay } from 'rxjs/operators';
import { Media, MediaService } from '@honoregaming/ui';
import { InstantGameCategory } from '@honoregaming/types';
import { BetCategoryConfigurationService } from '@honoregaming/core';
import { FavoriteManagerService } from 'projects/customer/hg-core/src/lib/services/domain/favorite-manager.service';
import { InstantGamesDataService } from '../../../services/instant-games-data.service';
import { CasinoTrackingService } from '../../../services/casino-tracking.service';
import { InstantGameCategoryComponentBase } from '../instant-game-category.component.base';
import { TelemetryService } from '@honoregaming/customer-core';

@Component({
  selector: 'hg-instant-game-highlights-category',
  templateUrl: './instant-game-highlights-category.component.html',
  styleUrls: ['./instant-game-highlights-category.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class InstantGameHighlightsCategoryComponent extends InstantGameCategoryComponentBase implements OnInit {
  @Input() category?: InstantGameCategory;

  topGamesNameFirstHalf?: string;
  topGamesNameLastHalf?: string;
  media$: Observable<Media>;
  Media = Media;
  providersCategoryId!: number;

  constructor(
    public readonly betCategoryConfigurationService: BetCategoryConfigurationService,
    public readonly cdRef: ChangeDetectorRef,
    public readonly favoriteManagerService: FavoriteManagerService,
    public readonly router: Router,
    public readonly telemetryService: TelemetryService,
    protected readonly instantGamesDataService: InstantGamesDataService,
    public readonly casinoTrackingService: CasinoTrackingService,
    @Optional() public readonly mediaService: MediaService
  ) {
    super(
      betCategoryConfigurationService,
      cdRef,
      instantGamesDataService,
      favoriteManagerService,
      router,
      telemetryService,
      casinoTrackingService
    );
  }

  ngOnInit(): void {
    this.media$ = this.mediaService.media$.pipe(shareReplay(1));
    let middle: number = Math.floor(this.category.name.length / 2);
    const before: number = this.category.name.lastIndexOf(' ', middle);
    const after: number = this.category.name.indexOf(' ', middle + 1);
    if (middle - before < after - middle || after === -1) {
      middle = before;
    } else {
      middle = after;
    }

    this.topGamesNameFirstHalf = this.category.name.substring(0, middle);
    this.topGamesNameLastHalf = this.category.name.substring(middle + 1);
    this.instantGamesDataService.providersCategoryId$.subscribe(id => (this.providersCategoryId = id));
  }

  trackBy(_index: number, item: { id: number }): number {
    return item.id;
  }
}
