import { Injectable } from '@angular/core';
import { TelemetryService } from '@honoregaming/customer-core';
import {
  CasinoLobbyCategoryNavType,
  CasinoMobileCategoryNavType,
  CasinoTrackedCategory
} from '../types/casino-tracking.types';

interface CasinoCategoryParams {
  category_name: string | null;
  category_id: number | null;
}

@Injectable({ providedIn: 'root' })
export class CasinoTrackingService {
  constructor(private readonly telemetryService: TelemetryService) {}

  trackLobbyCategorySelect(category: CasinoTrackedCategory, navType: CasinoLobbyCategoryNavType): void {
    this.telemetryService.trackEvent('casino_lobby_category_select', {
      nav_type: navType,
      ...this.toCategoryParams(category)
    });
  }

  trackLobbyGameSelect(gameName: string, category: CasinoTrackedCategory, position?: number): void {
    this.telemetryService.trackEvent('casino_lobby_game_select', {
      game_name: gameName,
      ...this.toCategoryParams(category),
      ...this.toPositionParams(position)
    });
  }

  trackCategoryGameSelect(gameName: string, category: CasinoTrackedCategory, position?: number): void {
    this.telemetryService.trackEvent('casino_category_game_select', {
      game_name: gameName,
      ...this.toCategoryParams(category),
      ...this.toPositionParams(position)
    });
  }

  trackDesktopSidebarCategorySelect(category: CasinoTrackedCategory): void {
    this.telemetryService.trackEvent('casino_desktop_sidebar_category_select', this.toCategoryParams(category));
  }

  trackMobileNavbarCategorySelect(category: CasinoTrackedCategory, navType: CasinoMobileCategoryNavType): void {
    this.telemetryService.trackEvent('casino_mobile_navbar_category_select', {
      nav_type: navType,
      ...this.toCategoryParams(category)
    });
  }

  private toCategoryParams(category: CasinoTrackedCategory | null): CasinoCategoryParams {
    return {
      category_name: category?.name ?? null,
      category_id: category?.id ?? null
    };
  }

  private toPositionParams(position?: number): { position?: number } {
    return position ? { position } : {};
  }
}
