import { Component, ChangeDetectionStrategy, OnInit, ChangeDetectorRef } from '@angular/core';
import { RouletteService } from '../../services/roulette.service';
import { RouletteGameHistory } from '@honoregaming/types';
import { rouletteItemColors, rouletteItemBorderColors } from '@honoregaming/ui';
import { DestroySubject } from '@honoregaming/core';
import { takeUntil } from 'rxjs/operators';

@Component({
  selector: 'hg-roulette-history',
  templateUrl: './roulette-history.component.html',
  styleUrls: ['./roulette-history.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class RouletteHistoryComponent extends DestroySubject implements OnInit {
  betSlipActive = false;
  rouletteHistory: RouletteGameHistory[] = [];
  loggedIn: boolean;

  colors = rouletteItemColors;
  borderColors = rouletteItemBorderColors;

  constructor(private rouletteService: RouletteService, private cdRef: ChangeDetectorRef) {
    super();
  }

  ngOnInit() {
    this.rouletteService.$rouletteHistory.pipe(takeUntil(this.destroy$)).subscribe(rouletteHistoryItem => {
      if (this.rouletteHistory.length === 20) {
        this.rouletteHistory.pop();
      }
      this.rouletteHistory.unshift(rouletteHistoryItem);
      this.cdRef.markForCheck();
    });
  }
}
