import { Inject, Injectable } from '@angular/core';
import { Observable, of } from 'rxjs';
import { distinctUntilChanged, map, shareReplay, switchMap } from 'rxjs/operators';
import { BetCategoryConfigurationService } from '@honoregaming/core';
import { InstantGame, InstantGameCategory, InstantGameCategoryType, InstantGameProvider } from '@honoregaming/types';
import {
  AuthService,
  CustomerOperatorConfiguration,
  customerOperatorConfigurationToken,
  FavoritesService
} from '@honoregaming/customer-core';
import { InstantGameService } from '@honoregaming/events';
import { globalConfiguration } from '@honoregaming/configuration';
import { InstantGamesRouteService } from './instant-games-route.service';

@Injectable({ providedIn: 'root' })
export class InstantGamesDataService {
  isUserConnected$ = this.authService.status$.pipe(map(status => status === 'connected'));
  instantGamesBetCategoryPath: string = this.betCategoryConfigurationService.getInstantGamesBetCategoryPath();
  baseAssetsPath: string = this.customerOperatorConfiguration.instantGamesConfiguration.insaGamesAssetsPath;
  assetspath?: string;

  // --- RAW CAT ---
  rawCategories$: Observable<InstantGameCategory[]> = this.instantGameService
    .getInstantGamesCategories()
    .pipe(shareReplay(1));

  rawFavorites$: Observable<InstantGame[]> = this.isUserConnected$.pipe(
    switchMap(isConnected => (isConnected ? this.favoritesService.getInstantGameFavorite() : of([])))
  );
  rawRecentlyPlayed$: Observable<InstantGame[]> = this.isUserConnected$.pipe(
    switchMap(isConnected =>
      isConnected ? this.instantGameService.getRecentlyPlayedInstantGame() : of<InstantGame[]>([])
    )
  );

  rawCustomersInPlay$: Observable<{
    [key: number]: number;
  }> = this.instantGameService.getCustomersInPlay().pipe(shareReplay(1));
  rawVendorGames$: Observable<InstantGame[]> = this.routeService.vendorName$.pipe(
    switchMap(vendor => (vendor ? this.instantGameService.getInstantGamesForVendor(vendor) : of([])))
  );
  rawCategory$: Observable<InstantGameCategory | null> = this.routeService.activeCategoryId$.pipe(
    switchMap(id => (id ? this.instantGameService.getInstantGameCategory(id) : of(null)))
  );
  rawBigWinners$: Observable<
    {
      customer: string;
      paidAmount: number;
      instantGame: InstantGame;
    }[]
  > = this.instantGameService.getBigWinners().pipe(
    map(items => {
      const emptyFavorites: Set<number> = new Set<number>();
      const emptyCustomers: Record<number, number> = {};

      return items
        .filter(item => !!item.instantGame)
        .map(item => ({
          customer: item.customer,
          paidAmount: item.paidAmount,
          instantGame: this.mapGame(item.instantGame, emptyFavorites, emptyCustomers)
        }));
    }),
    shareReplay(1)
  );
  rawWinnersStream$: Observable<
    {
      customer: string;
      paidAmount: number;
      instantGame: InstantGame;
    }[]
  > = this.instantGameService.getWinnersStream().pipe(
    map(items => {
      const emptyFavorites: Set<number> = new Set<number>();
      const emptyCustomers: Record<number, number> = {};

      return items
        .filter(item => !!item.instantGame)
        .map(item => ({
          customer: item.customer,
          paidAmount: item.paidAmount,
          instantGame: this.mapGame(item.instantGame, emptyFavorites, emptyCustomers)
        }));
    }),
    shareReplay(1)
  );

  constructor(
    public readonly instantGameService: InstantGameService,
    public readonly favoritesService: FavoritesService,
    public readonly authService: AuthService,
    public readonly betCategoryConfigurationService: BetCategoryConfigurationService,
    private readonly routeService: InstantGamesRouteService,
    @Inject(customerOperatorConfigurationToken)
    public readonly customerOperatorConfiguration: CustomerOperatorConfiguration
  ) {
    const regex: RegExp = new RegExp(/^(https?:\/\/[^/]+)/); // Permet de matcher l'url de base
    const matches: RegExpExecArray = regex.exec(globalConfiguration.assetsPath);
    this.assetspath = matches ? matches[0] : '';
  }

  get providersCategoryId$(): Observable<number | null> {
    return this.rawCategories$.pipe(
      map(categories => categories.find(category => category.type === InstantGameCategoryType.Providers)?.id ?? null),
      distinctUntilChanged()
    );
  }

  public mapGame(game: InstantGame, favorites?: Set<number>, customers?: Record<number, number>): InstantGame {
    const isFavorite: boolean = favorites?.has(game.id) ?? false;
    const customersInPlay: number = customers?.[game.id] ?? null;
    // URL providers-standar
    const computedUrl: string = `/${this.instantGamesBetCategoryPath}/` + game.url;

    // Provider-specific
    switch (game.provider) {
      case InstantGameProvider.InsaGames:
        return {
          ...game,
          computedUrl,
          isFavorite,
          customersInPlay,
          imageUrl: game.imageUrl || `${this.baseAssetsPath}${game.name.toLowerCase()}/thumbnail.png`
        };

      case InstantGameProvider.GameTech:
        return {
          ...game,
          computedUrl,
          isFavorite,
          customersInPlay,
          imageUrl: game.imageUrl.startsWith('http')
            ? game.imageUrl
            : `${this.assetspath}/instant-game-providers/${game.imageUrl}`
        };

      default:
        return {
          ...game,
          computedUrl,
          isFavorite,
          customersInPlay
        };
    }
  }
}
