import { Component, AfterViewInit, ChangeDetectionStrategy, ViewChild, ElementRef } from '@angular/core';
import { BehaviorSubject, Observable } from 'rxjs';
import { switchMap } from 'rxjs/operators';
import { InstantGameTournament, TournamentFilter } from '@honoregaming/types';
import { InstantGamesTournamentsService } from '../../../services/instant-games-tournaments.service';

@Component({
  selector: 'hg-instant-games-tournaments-list',
  templateUrl: './instant-games-tournaments-list.component.html',
  styleUrls: ['./instant-games-tournaments-list.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class InstantGamesTournamentsListComponent implements AfterViewInit {
  @ViewChild('menu') menu!: ElementRef;

  readonly filters: TournamentFilter[] = ['ALL', 'Upcoming', 'Ongoing', 'Finished'];
  readonly activeFilter$: BehaviorSubject<TournamentFilter> = new BehaviorSubject<TournamentFilter>('ALL');

  readonly tournaments$: Observable<InstantGameTournament[]> = this.activeFilter$.pipe(
    switchMap(filter => this.tournamentsService.getTournamentsByStatus(filter))
  );
  readonly loading$: Observable<boolean> = this.tournamentsService.loading$;
  readonly error$: Observable<string | null> = this.tournamentsService.error$;

  constructor(private readonly tournamentsService: InstantGamesTournamentsService) {}

  ngAfterViewInit(): void {
    const el: HTMLElement = this.menu.nativeElement;
    const fits: boolean = el.scrollWidth <= el.clientWidth;

    if (fits) {
      el.classList.add('centered');
    }
  }

  onFilterChange(filter: TournamentFilter): void {
    this.activeFilter$.next(filter);
  }
}
