import { AfterViewInit, ChangeDetectorRef, Directive, ElementRef, ViewChild } from '@angular/core';
import { Router } from '@angular/router';
import { InstantGame, InstantGameCategory, InstantGameCategoryType } from '@honoregaming/types';
import { BetCategoryConfigurationService, DestroySubject } from '@honoregaming/core';
import { FavoriteManagerService } from 'projects/customer/hg-core/src/lib/services/domain/favorite-manager.service';
import { InstantGamesDataService } from '../../services/instant-games-data.service';
import { CasinoTrackingService } from '../../services/casino-tracking.service';
import { CasinoLobbyCategoryNavType, CasinoTrackedCategory } from '../../types/casino-tracking.types';
import { TelemetryService } from '@honoregaming/customer-core';

@Directive()
export abstract class InstantGameCategoryComponentBase extends DestroySubject implements AfterViewInit {
  mouseMove: boolean = false;
  mouseDown: boolean = false;
  startX: number = 0;
  startY: number = 0;
  movementThreshold: number = 5;
  scrollLeft: number = 0;
  scrollValue: number = 500;
  arrowLeftVisible: boolean = false;
  arrowRightVisible: boolean = false;
  private lastScrollLeft: number = 0;
  private lastScrollWidth: number = 0;
  InstantGameCategoryType = InstantGameCategoryType;
  instantGamesBetCategoryPath: string = this.betCategoryConfigurationService.getInstantGamesBetCategoryPath();

  @ViewChild('categoryGames') categoryGames!: ElementRef;

  constructor(
    public readonly betCategoryConfigurationService: BetCategoryConfigurationService,
    public readonly cdRef: ChangeDetectorRef,
    protected readonly instantGamesDataService: InstantGamesDataService,
    public readonly favoriteManagerService: FavoriteManagerService,
    public readonly router: Router,
    public readonly telemetryService: TelemetryService,
    public readonly casinoTrackingService: CasinoTrackingService
  ) {
    super();
  }

  ngAfterViewInit(): void {
    requestAnimationFrame(() => {
      this.updateArrowVisibility();
    });
  }

  moveEvent(e: MouseEvent, el: HTMLDivElement): void {
    e.stopImmediatePropagation();

    if (!this.mouseDown) {
      return;
    }

    const x: number = e.pageX - el.offsetLeft;
    const y: number = e.pageY - el.offsetTop;
    const moveX: number = Math.abs(x - this.startX);
    const moveY: number = Math.abs(y - this.startY);

    if (moveX > this.movementThreshold || moveY > this.movementThreshold) {
      this.mouseMove = true;
    }

    if (this.mouseMove) {
      const scroll: number = x - this.startX;
      el.scrollLeft = this.scrollLeft - scroll;
    }
  }

  stopDragging(event: MouseEvent): void {
    event.stopImmediatePropagation();
    this.mouseDown = false;
    this.updateArrowVisibility();
  }

  startDragging(e: MouseEvent, el: HTMLElement): void {
    e.preventDefault();
    e.stopImmediatePropagation();
    this.mouseDown = true;
    this.mouseMove = false;
    this.startX = e.pageX - el.offsetLeft;
    this.startY = e.pageY - el.offsetTop;
    this.scrollLeft = el.scrollLeft;
  }

  swipe(): void {
    this.updateArrowVisibility();
  }

  updateArrowVisibility(): void {
    const el: HTMLElement = this.categoryGames?.nativeElement;
    if (!el) return;
    const scrollLeft: number = el.scrollLeft;
    const scrollWidth: number = el.scrollWidth;
    if (scrollLeft === this.lastScrollLeft && scrollWidth === this.lastScrollWidth) {
      return;
    }
    this.lastScrollLeft = scrollLeft;
    this.lastScrollWidth = scrollWidth;
    this.arrowLeftVisible = scrollLeft > 0;
    this.arrowRightVisible = scrollLeft + el.clientWidth < scrollWidth - 1;
    this.cdRef.detectChanges();
  }

  onNextPosition(): void {
    const el: HTMLElement = this.categoryGames.nativeElement;
    el.scrollTo({
      left: el.scrollLeft + this.scrollValue,
      behavior: 'smooth'
    });

    setTimeout(() => this.updateArrowVisibility(), this.scrollValue);
  }

  onPreviousPosition(): void {
    const el: HTMLElement = this.categoryGames.nativeElement;
    el.scrollTo({
      left: el.scrollLeft - this.scrollValue,
      behavior: 'smooth'
    });

    setTimeout(() => this.updateArrowVisibility(), this.scrollValue);
  }

  redirect(url: string, gameName: string, category?: CasinoTrackedCategory, position?: number): void {
    if (!this.mouseMove) {
      this.telemetryService.trackEvent('casino_game_click', { game_name: gameName });

      if (category) {
        this.casinoTrackingService.trackLobbyGameSelect(gameName, category, position);
      }

      if (category?.id) {
        this.router.navigate([url], {
          queryParams: { categoryId: category.id }
        });
      } else {
        this.router.navigate([url]);
      }
    }

    this.mouseMove = false;
  }

  redirectAnimated(category: InstantGameCategory): void {
    if (!this.mouseMove) {
      const highlightedIndex: number = category.instantGames.findIndex((game: InstantGame) => game.highlighted);
      const highlightedGame: InstantGame = category.instantGames[highlightedIndex];
      this.casinoTrackingService.trackLobbyGameSelect(highlightedGame.name, category, highlightedIndex + 1);
      this.router.navigate([highlightedGame.computedUrl], {
        queryParams: { categoryId: category.id }
      });
    }
    this.mouseMove = false;
  }

  onCategoryClick(category: CasinoTrackedCategory, navType: CasinoLobbyCategoryNavType = 'button'): void {
    this.casinoTrackingService.trackLobbyCategorySelect(category, navType);
    this.router.navigate([`/${this.instantGamesBetCategoryPath}/category`, category.id]);
  }

  handleClick(event: MouseEvent): void {
    if (this.mouseMove) {
      event.preventDefault();
      event.stopPropagation();
      event.stopImmediatePropagation();
    }
    this.mouseMove = false;
  }

  onVendorClick(categoryId: number, providerName: string): void {
    if (!this.mouseMove) {
      this.telemetryService.trackEvent('casino_vendor_click', {
        provider_name: providerName
      });
      this.router.navigate([`/${this.instantGamesBetCategoryPath}/category`, categoryId, providerName]);
    }
    this.mouseMove = false;
  }

  toggleFavorited(game: InstantGame, event: Event, categoryType = InstantGameCategoryType.Classic): void {
    event.stopPropagation();
    event.preventDefault();
    const isFavoriteCategory: boolean = categoryType === InstantGameCategoryType.Favorites;

    this.favoriteManagerService
      .toggle(game, {
        undoContext: isFavoriteCategory,
        undoAction: () => this.toggleFavorited(game, event, categoryType)
      })
      .subscribe();
  }
}
