import {
  Component,
  ChangeDetectionStrategy,
  OnInit,
  ChangeDetectorRef,
  Optional,
  ElementRef,
  ViewChild,
  OnDestroy,
  Inject,
  PLATFORM_ID,
  HostListener
} from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { Location } from '@angular/common';
import { finalize, takeUntil } from 'rxjs/operators';
import { BetCategoryConfigurationService, BroadcastingService, LocalStorageService } from '@honoregaming/core';
import { InstantGame, InstantGameMode, InstantGameProvider, InstantGameTournament } from '@honoregaming/types';
import {
  AuthService,
  FavoritesService,
  CustomerOperatorConfiguration,
  customerOperatorConfigurationToken,
  IdleService,
  TelemetryService
} from '@honoregaming/customer-core';
import { I18nService } from '@honoregaming/i18n';
import { Media, MediaService, MessageService, WarningDataComponent } from '@honoregaming/ui';
import { InstantGameService } from '@honoregaming/events';
import { ToasterService } from '@honoregaming/ui';
import { NavBarService } from 'projects/customer/customer/src/app/services';
import { FavoriteManagerService } from 'projects/customer/hg-core/src/lib/services/domain/favorite-manager.service';
import { InstantGamesHomeComponent } from '../instant-games-home/instant-games-home.component';
import { InstantGamesRouteService } from '../../services/instant-games-route.service';
import { InstantGamesFiltersService } from '../../services/instant-games-filters.service';
import { InstantGamesTournamentsService } from '../../services/instant-games-tournaments.service';

@Component({
  selector: 'hg-bg-game',
  templateUrl: './bg-game.component.html',
  styleUrls: ['./bg-game.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class BgGameComponent extends InstantGamesHomeComponent implements OnInit, OnDestroy {
  public loading: boolean;
  public gameUrl: string;
  public width: number;
  public height: number;
  public maxMobileHeight: string;
  public game: InstantGame;

  public mode: InstantGameMode;
  public InstantGameMode = InstantGameMode;
  public loggedIn: boolean;
  public isGameReady = false;
  public isGameLoaded = false;
  public liveGameImage: string;
  public funModeAvailable: boolean;
  public showSwitchMode: boolean;

  public isScrollVisible = true;

  public gameName: string;
  warnOnDataConsumption = this.customerOperatorConfiguration.onlineConfiguration?.warnOnDataConsumption;
  private readonly APP_BANNER_STORAGE_KEY = 'appBannerDisplay';

  @ViewChild('gameIFrame', { static: true }) iframe: ElementRef;

  instantGamesBetCategoryPath = this.betCategoryConfigurationService.getInstantGamesBetCategoryPath();
  isMobileAppBannerDisplayed: boolean = !this.storageService.getItem(this.APP_BANNER_STORAGE_KEY);

  private currentOrientation?: 'landscape' | 'portrait';
  private bindingListeners: (event: MessageEvent<any>) => void;
  private bindingOrientationListeners: (event: MessageEvent<any>) => void;
  private resizeTimeout: any;
  private latestTournaments: InstantGameTournament[] = [];
  private readonly BANNER_HEIGHT = 34;
  private readonly NAV_BAR_HEIGHT = 65;
  private readonly APP_BANNER_HEIGHT = 62;
  private readonly HEADER_PORTRAIT_HEIGHT = 55;
  private readonly HEADER_LANDSCAPE_HEIGHT = 70;
  private readonly SWITCH_MODE_HEIGHT = 57;
  private readonly SIZE_CHANGE_THRESHOLD_IN_PIXELS = 10;

  constructor(
    private route: ActivatedRoute,
    router: Router,
    authService: AuthService,
    instantGameService: InstantGameService,
    cdRef: ChangeDetectorRef,
    private storageService: LocalStorageService,
    public messageService: MessageService,
    public navBarService: NavBarService,
    i18nService: I18nService,
    public readonly favoriteManagerService: FavoriteManagerService,
    public readonly instantGamesFiltersService: InstantGamesFiltersService,
    public readonly instantGamesRouteService: InstantGamesRouteService,
    private readonly tournamentsService: InstantGamesTournamentsService,
    public location: Location,
    betCategoryConfigurationService: BetCategoryConfigurationService,
    public favoritesService: FavoritesService,
    public toasterService: ToasterService,
    private broadcastingService: BroadcastingService,
    public telemetryService: TelemetryService,
    @Inject(customerOperatorConfigurationToken) public customerOperatorConfiguration: CustomerOperatorConfiguration,
    @Optional() public mediaService: MediaService,
    @Optional() private idleService: IdleService,
    @Inject(PLATFORM_ID) platformId
  ) {
    super(
      instantGameService,
      i18nService,
      cdRef,
      route,
      router,
      location,
      betCategoryConfigurationService,
      favoritesService,
      navBarService,
      messageService,
      favoriteManagerService,
      instantGamesFiltersService,
      instantGamesRouteService,
      authService,
      customerOperatorConfiguration,
      document,
      platformId,
      mediaService
    );

    this.bindingListeners = ev => {
      const handlers: { [key: string]: () => void } = {
        gameRoundStarted: this.onGameRoundStarted.bind(this),
        gameLoaded: this.onGameLoaded.bind(this)
      };

      let parsed: { event?: string; data?: { event?: string } };
      try {
        parsed = typeof ev.data === 'string' ? JSON.parse(ev.data) : ev.data;
      } catch {
        return; // not a JSON message we care about
      }

      const eventName: string | undefined = parsed?.event ?? parsed?.data?.event;

      const handler: () => void = eventName ? handlers[eventName] : undefined;
      if (handler) {
        handler();
      }
    };

    this.bindingOrientationListeners = ev => {
      const handlers: { [key: string]: () => void } = {
        resize: this.onScreenEvent.bind(this)
      };

      const handler: () => void = handlers[ev.type];

      if (handler) {
        handler();
      }
    };
  }

  ngOnInit(): void {
    super.ngOnInit();

    this.broadcastingService.broadcast('display-require-fullscreen', true);

    this.broadcastingService
      .register('mobile-banner-closed')
      .pipe(takeUntil(this.destroy$))
      .subscribe(_ => {
        this.isMobileAppBannerDisplayed = false;
        this.setGameDimensions(false);
        this.cdRef.markForCheck();
      });

    if (this.warnOnDataConsumption) {
      this.messageService
        .sendComponentMessage(
          WarningDataComponent,
          {
            messageKey: 'WARN.DATA.GAME'
          },
          { queue: true },
          this.destroy$,
          true
        )
        .closed.subscribe(result => {
          if (!result) {
            this.location.back();
            return;
          }
          this.init();
        });
    } else {
      this.init();
    }
  }

  // tslint:disable-next-line: use-life-cycle-interface
  ngOnDestroy(): void {
    super.ngOnDestroy();

    window.removeEventListener('message', this.bindingListeners, false);
    window.removeEventListener('resize', this.bindingOrientationListeners);
    this.idleService?.startWatching(10 * 6e4);
    this.navBarService.setNavBarActive(true);

    this.broadcastingService.broadcast('display-require-fullscreen', false);
  }

  @HostListener('window:touchmove', ['$event'])
  touchMoveOnMobile(event): void {
    if (event.touches) {
      if (event.targetTouches.length == 1 && window.scrollY > 100) {
        this.isScrollVisible = false;
      } else {
        this.isScrollVisible = true;
      }
      event.stopPropagation();
    }
  }

  @HostListener('window:touchend', ['$event'])
  touchEndOnMobile(event): void {
    setTimeout(() => {
      if (window.scrollY <= 100) {
        this.isScrollVisible = true;
        this.cdRef.markForCheck();
        event.stopPropagation();
      }
    }, 500);
  }

  iFrameLoaded(): void {
    this.loading = false;
    this.isGameReady = true;
    this.listenEventIframe();
  }

  switchMode(): void {
    this.isGameReady = false;
    this.storageService.setItem(`external-game-mode_${this.gameName}`, InstantGameMode.Real);
    this.mode = InstantGameMode.Real;
    this.showSwitchMode = false;
    this.setGameDimensions(false);
    this.cdRef.markForCheck();

    this.loadGame(true);
  }

  scrollToBottom(): void {
    this.isScrollVisible = false;
    window.scroll({
      top: this.height,
      left: 0,
      behavior: 'smooth'
    });
  }

  private init(): void {
    this.idleService?.stopWatching();

    this.loading = true;
    this.loggedIn = this.authService.isAuthenticated();

    this.tournamentsService.tournaments$.pipe(takeUntil(this.destroy$)).subscribe(tournaments => {
      this.latestTournaments = tournaments;
      if (this.game && this.mediaService?.media <= Media.md) {
        this.setGameDimensions(false);
        this.cdRef.markForCheck();
      }
    });

    this.authService.status$.pipe(takeUntil(this.destroy$)).subscribe(me => {
      if (me === 'connected' && !this.loggedIn && this.gameName) {
        this.gameUrl = '';
        this.isGameReady = false;
        this.loggedIn = this.authService.isAuthenticated();
        this.cdRef.markForCheck();

        this.loadGame(true);
      }
    });

    this.route.params.subscribe(params => {
      this.gameName = params['slug'];
      this.loadGame();
    });
  }

  private listenEventIframe(): void {
    window.addEventListener('message', this.bindingListeners, false);
    window.addEventListener('resize', this.bindingOrientationListeners);
  }

  private onGameRoundStarted(): void {
    this.authService.tryRefresh().pipe(takeUntil(this.destroy$)).subscribe();
  }

  private onScreenEvent(): void {
    let newOrientation: 'portrait' | 'landscape' = this.getOrientation();

    const newHeight: number = window.innerHeight - (this.getBannerHeight() + this.getHeaderHeight());

    if (
      newOrientation !== this.currentOrientation ||
      Math.abs(newHeight - this.height) >= this.SIZE_CHANGE_THRESHOLD_IN_PIXELS
    ) {
      clearTimeout(this.resizeTimeout);
      this.resizeTimeout = setTimeout(() => {
        this.currentOrientation = newOrientation;
        this.setGameDimensions(false);
        this.cdRef.markForCheck();
      }, 100);
    }
  }

  private getOrientation(): 'landscape' | 'portrait' {
    // Legacy devices expose window.orientation
    if (typeof window.orientation === 'number') {
      return Math.abs(window.orientation) === 90 ? 'landscape' : 'portrait';
    }
    // Fallback: compare viewport dimensions
    return window.innerWidth > window.innerHeight ? 'landscape' : 'portrait';
  }

  private loadGame(reloadUrl?: boolean): void {
    this.loading = true;
    this.cdRef.markForCheck();

    this.instantGameService
      .getInstantGame(InstantGameProvider.BoomingGames, this.gameName)
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => this.cdRef.markForCheck())
      )
      .subscribe((game: InstantGame) => this.setupGame(game, reloadUrl));
  }

  private setupGame(game: InstantGame, reloadUrl?: boolean): void {
    if (!game) {
      this.router.navigate([`/${this.instantGamesBetCategoryPath}`]);
      return;
    }

    this.game = game;
    this.navBarService.setNavBarActive(game.navBar);
    this.funModeAvailable = game.configuration.funModeAvailable;

    // Logged-out preview for live / non-fun-mode games: static image, no iframe.
    if ((!this.funModeAvailable || game.isLive) && !this.loggedIn) {
      this.liveGameImage = game.imageUrl;
      this.setGameDimensions(true);
      this.loading = false;
      return;
    }

    this.setupPlayableGame(game, reloadUrl);
  }

  private setupPlayableGame(game: InstantGame, reloadUrl?: boolean): void {
    this.resolveGameMode(game);
    this.showSwitchMode = this.mode === InstantGameMode.Demo && this.loggedIn;

    this.setGameDimensions(false);

    this.gameUrl =
      game.isLive || (this.mode === InstantGameMode.Real && this.authService.isAuthenticated())
        ? game.configuration.userConnectedUrl
        : game.configuration.userDisconnectedUrl;

    // Force iFrame to reload and raise again the onload event
    if (reloadUrl) {
      this.gameUrl += '';
    }

    this.isGameLoaded = false; // gate closed until (re)loaded client signals gameLoaded
    this.iframe.nativeElement.src = this.gameUrl;
  }

  private resolveGameMode(game: InstantGame): void {
    if (game.isLive || !this.funModeAvailable) {
      this.storageService.setItem(`external-game-mode_${this.gameName}`, InstantGameMode.Real);
      this.mode = InstantGameMode.Real;
    } else {
      this.mode = this.storageService.getItem(`external-game-mode_${this.gameName}`) || InstantGameMode.Demo;
    }
  }

  private setGameDimensions(isLivePreview: boolean): void {
    if (isLivePreview) {
      this.width = 1;
      this.height = 1;
      return;
    }

    if (this.mediaService?.media <= Media.md) {
      const bannerHeight: number = this.getBannerHeight();
      const headerHeight: number = this.getHeaderHeight();
      this.height = window.innerHeight - (headerHeight + bannerHeight);
      this.width = 0;
    } else {
      this.width = 0;
      this.height = 0;
    }
  }

  private getBannerHeight(): number {
    return this.latestTournaments.some(
      (tournament: InstantGameTournament) =>
        tournament.status === 'Ongoing' &&
        tournament.isCustomerAlreadyParticipating &&
        tournament.instantGames?.some((game: InstantGame) => game.id === this.game?.id)
    )
      ? this.BANNER_HEIGHT
      : 0;
  }

  private getHeaderHeight(): number {
    // Mobile with fixed dimensions
    const navBarHeight: number = this.game.navBar ? this.NAV_BAR_HEIGHT : 0;
    const appBannerHeight: number = this.isMobileAppBannerDisplayed ? this.APP_BANNER_HEIGHT : 0;
    const headerHeight: number =
      this.getOrientation() === 'landscape' ? this.HEADER_LANDSCAPE_HEIGHT : this.HEADER_PORTRAIT_HEIGHT;
    const switchModeHeight: number = this.showSwitchMode ? this.SWITCH_MODE_HEIGHT : 0;

    return navBarHeight + appBannerHeight + headerHeight + switchModeHeight;
  }

  private onGameLoaded(): void {
    this.isGameLoaded = true;
    this.cdRef.markForCheck();
  }
}
