import { Directive, OnInit, Inject, PLATFORM_ID, ChangeDetectorRef } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { DOCUMENT, isPlatformBrowser } from '@angular/common';
import { Observable } from 'rxjs';
import { map, takeUntil } from 'rxjs/operators';
import { BetCategoryConfigurationService, DestroySubject } from '@honoregaming/core';
import { InstantGameCategory, InstantGameCategoryType } from '@honoregaming/types';
import { AuthService } from '@honoregaming/customer-core';
import { authServiceToken } from '@honoregaming/authentication';
import { InstantGamesDataService } from '../../services/instant-games-data.service';
import { InstantGamesRouteService } from '../../services/instant-games-route.service';
import { CasinoTrackingService } from '../../services/casino-tracking.service';

@Directive()
export abstract class InstantGamesMenuBaseComponent extends DestroySubject implements OnInit {
  public isUserConnected: boolean = this.authService.isAuthenticated();
  instantGamesBetCategoryPath: string =
    this.instantGamesBetCategoryConfigurationService.getInstantGamesBetCategoryPath();
  categoryId$: Observable<string | null> = this.instantGamesRouteService.activeCategoryId$;
  isTournamentRoute$: Observable<boolean> = this.instantGamesRouteService.activeTournament$;
  InstantGameCategoryType = InstantGameCategoryType;
  categories$: Observable<InstantGameCategory[]> = this.instantGamesDataService.rawCategories$;
  isOnAll$: Observable<boolean> = this.instantGamesRouteService.isOnAll$;

  readonly sortedCategories$ = this.categories$.pipe(
    map(categories =>
      [...categories].sort((catLeft, catRight) => {
        const order = [InstantGameCategoryType.Favorites, InstantGameCategoryType.Tournaments];
        const leftIndex: number = order.indexOf(catLeft.type);
        const rightIndex: number = order.indexOf(catRight.type);
        if (leftIndex !== -1 && rightIndex !== -1) {
          return leftIndex - rightIndex;
        }
        if (leftIndex !== -1) {
          return -1;
        }
        if (rightIndex !== -1) {
          return 1;
        }
        return 0;
      })
    )
  );

  constructor(
    public readonly activatedRoute: ActivatedRoute,
    public readonly router: Router,
    public readonly cdRef: ChangeDetectorRef,
    private readonly instantGamesBetCategoryConfigurationService: BetCategoryConfigurationService,
    public readonly instantGamesDataService: InstantGamesDataService,
    private readonly instantGamesRouteService: InstantGamesRouteService,
    private readonly casinoTrackingService: CasinoTrackingService,
    @Inject(authServiceToken) public readonly authService: AuthService,
    @Inject(DOCUMENT) public document,
    @Inject(PLATFORM_ID) public platformId
  ) {
    super();
  }

  ngOnInit(): void {
    this.authService.status$.pipe(takeUntil(this.destroy$)).subscribe(status => {
      const isConnected: boolean = status === 'connected';
      if (this.isUserConnected !== isConnected) {
        this.isUserConnected = isConnected;
        this.cdRef.markForCheck();
      }
    });
  }

  onCategoryClick(category?: InstantGameCategory): void {
    if (category) {
      this.casinoTrackingService.trackDesktopSidebarCategorySelect(category);
    }

    if (category?.type === InstantGameCategoryType.Tournaments) {
      this.router.navigate([`/${this.instantGamesBetCategoryPath}/tournaments`]);
      return;
    }

    if (!category?.id) {
      this.router.navigate([`/${this.instantGamesBetCategoryPath}`]);
      return;
    }

    this.router.navigate([`/${this.instantGamesBetCategoryPath}/category`, category.id]);

    if (isPlatformBrowser(this.platformId)) {
      setTimeout(() => {
        const anchorElement: HTMLElement | null = this.document.getElementById('is-selected');
        if (anchorElement) {
          anchorElement.scrollIntoView({
            behavior: 'smooth',
            block: 'nearest',
            inline: 'center'
          });
        }
      });
    }
  }

  trackByCategory(_index: number, category: InstantGameCategory): number {
    return category.id;
  }
}
