import {
  Component,
  ChangeDetectionStrategy,
  OnInit,
  ChangeDetectorRef,
  Optional,
  ElementRef,
  ViewChild,
  OnDestroy,
  Inject,
  PLATFORM_ID,
  HostListener
} from '@angular/core';
import {
  ApplicationStateService,
  BetCategoryConfigurationService,
  BroadcastingService,
  LocalStorageService
} from '@honoregaming/core';
import { isPlatformBrowser, Location } from '@angular/common';
import { ActivatedRoute, Router } from '@angular/router';
import { finalize, takeUntil } from 'rxjs/operators';

import { InstantGame, InstantGameMode, InstantGameProvider } from '@honoregaming/types';
import {
  AuthService,
  FavoritesService,
  CustomerOperatorConfiguration,
  customerOperatorConfigurationToken,
  IdleService
} from '@honoregaming/customer-core';
import { Media, MediaService, MessageService, WarningDataComponent } from '@honoregaming/ui';
import { globalConfiguration } from '@honoregaming/configuration';
import { I18nService } from '@honoregaming/i18n';
import { InstantGameService } from '@honoregaming/events';
import { NavBarService } from 'projects/customer/customer/src/app/services';
import { FavoriteManagerService } from 'projects/customer/hg-core/src/lib/services/domain/favorite-manager.service';
import { InstantGamesHomeComponent } from '../instant-games-home/instant-games-home.component';
import { InstantGamesFiltersService } from '../../services/instant-games-filters.service';
import { InstantGamesRouteService } from '../../services/instant-games-route.service';

@Component({
  selector: 'hg-aviator-llc-game',
  templateUrl: './aviator-llc-game.component.html',
  styleUrls: ['./aviator-llc-game.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class AviatorLlcGameComponent extends InstantGamesHomeComponent implements OnInit, OnDestroy {
  @ViewChild('gameIFrame', { static: true }) iframe?: ElementRef;

  public loading?: boolean;
  public gameUrl?: string;
  public width?: number;
  public height?: number;
  public maxMobileHeight?: string;
  public game?: InstantGame;
  public mode?: InstantGameMode;
  public InstantGameMode = InstantGameMode;
  public loggedIn?: boolean;
  public isGameReady: boolean = false;
  public redirectionObserverArmed: boolean = false;
  public funModeAvailable?: boolean;
  public showSwitchMode?: boolean;
  public isScrollVisible: boolean = true;
  public gameName?: string;
  warnOnDataConsumption: boolean = this.customerOperatorConfiguration.onlineConfiguration?.warnOnDataConsumption;
  instantGamesBetCategoryPath: string = this.betCategoryConfigurationService.getInstantGamesBetCategoryPath();
  assetspath?: string;
  public gameImage?: string;

  constructor(
    private readonly route: ActivatedRoute,
    public readonly router: Router,
    public readonly authService: AuthService,
    public readonly instantGameService: InstantGameService,
    public readonly cdRef: ChangeDetectorRef,
    private readonly storageService: LocalStorageService,
    public readonly messageService: MessageService,
    public readonly navBarService: NavBarService,
    public readonly i18nService: I18nService,
    public readonly location: Location,
    public readonly betCategoryConfigurationService: BetCategoryConfigurationService,
    public readonly favoritesService: FavoritesService,
    private readonly broadcastingService: BroadcastingService,
    private readonly applicationStateService: ApplicationStateService,
    public readonly favoriteManagerService: FavoriteManagerService,
    public readonly instantGamesFiltersService: InstantGamesFiltersService,
    public readonly instantGamesRouteService: InstantGamesRouteService,
    @Inject(customerOperatorConfigurationToken)
    public readonly customerOperatorConfiguration: CustomerOperatorConfiguration,
    @Optional() public readonly mediaService: MediaService,
    @Optional() private readonly idleService: IdleService,
    @Inject(PLATFORM_ID) platformId
  ) {
    super(
      instantGameService,
      i18nService,
      cdRef,
      route,
      router,
      location,
      betCategoryConfigurationService,
      favoritesService,
      navBarService,
      messageService,
      favoriteManagerService,
      instantGamesFiltersService,
      instantGamesRouteService,
      authService,
      customerOperatorConfiguration,
      document,
      platformId,
      mediaService
    );
  }

  ngOnInit(): void {
    super.ngOnInit();

    const regex: RegExp = new RegExp(/^(https?:\/\/[^\/]+)/); // Permet de matcher l'url de base
    const matches: RegExpExecArray = regex.exec(globalConfiguration.assetsPath);
    this.assetspath = matches ? matches[0] : '';

    this.broadcastingService.broadcast('display-require-fullscreen', true);

    if (this.warnOnDataConsumption) {
      this.messageService
        .sendComponentMessage(
          WarningDataComponent,
          {
            messageKey: 'WARN.DATA.GAME'
          },
          { queue: true },
          this.destroy$,
          true
        )
        .closed.subscribe(result => {
          if (!result) {
            this.location.back();
            return;
          }
          this.init();
        });
    } else {
      this.init();
    }
  }

  ngOnDestroy(): void {
    super.ngOnDestroy();

    this.idleService?.startWatching(10 * 6e4);
    this.navBarService.setNavBarActive(true);

    this.broadcastingService.broadcast('display-require-fullscreen', false);
  }

  @HostListener('window:touchmove', ['$event'])
  touchMoveOnMobile(event): void {
    if (event.touches) {
      if (event.targetTouches.length == 1 && window.scrollY > 100) {
        this.isScrollVisible = false;
      } else {
        this.isScrollVisible = true;
      }
      event.stopPropagation();
    }
  }

  @HostListener('window:touchend', ['$event'])
  touchEndOnMobile(event): void {
    setTimeout(() => {
      if (window.scrollY <= 100) {
        this.isScrollVisible = true;
        this.cdRef.markForCheck();
        event.stopPropagation();
      }
    }, 500);
  }

  public iFrameLoaded(): void {
    this.loading = false;
    this.isGameReady = true;

    // Arm the redirection observer only after the game's own load event has fully
    // dispatched: change detection can run between two listeners of the same load
    // event, so arming synchronously would let the observer treat the game's first
    // (cross-origin) load as a redirection and kick the player back to the lobby.
    setTimeout(() => {
      this.redirectionObserverArmed = true;
      this.cdRef.markForCheck();
    });
  }

  switchMode(): void {
    this.isGameReady = false;
    this.redirectionObserverArmed = false;
    this.storageService.setItem(`external-game-mode_${this.gameName}`, InstantGameMode.Real);
    this.mode = InstantGameMode.Real;
    this.height = window.innerHeight - (this.game.navBar ? 65 : 0) - 55;
    this.cdRef.markForCheck();

    this.loadGame(true);
  }

  scrollToBottom(): void {
    this.isScrollVisible = false;
    window.scroll({
      top: this.height,
      left: 0,
      behavior: 'smooth'
    });
  }

  private init(): void {
    this.loading = true;
    this.loggedIn = this.authService.isAuthenticated();

    this.authService.status$.pipe(takeUntil(this.destroy$)).subscribe(me => {
      if (me === 'connected' && !this.loggedIn && this.gameName) {
        this.gameUrl = '';
        this.isGameReady = false;
        this.redirectionObserverArmed = false;
        this.loggedIn = this.authService.isAuthenticated();
        this.cdRef.markForCheck();

        this.loadGame(true);
      }
    });

    this.route.params.pipe(takeUntil(this.destroy$)).subscribe(params => {
      this.gameName = params['gameName'];
      this.loadGame();
    });

    if (isPlatformBrowser(this.platformId)) {
      this.applicationStateService.isReady$.subscribe(() => {
        this.idleService?.stopWatching();
      });
    }

    this.idleService?.stopWatching();
  }

  private loadGame(reloadUrl?: boolean): void {
    this.loading = true;
    this.cdRef.markForCheck();

    this.instantGameService
      .getInstantGame(InstantGameProvider.AviatorLlc, this.gameName)
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.cdRef.markForCheck();
        })
      )
      .subscribe((game: InstantGame) => {
        if (game) {
          this.game = game;
          this.navBarService.setNavBarActive(game.navBar);

          this.funModeAvailable = game.configuration.funModeAvailable;

          if ((!this.funModeAvailable || game.isLive) && !this.loggedIn) {
            this.width = 1;
            this.height = 1;
            this.gameImage = `${game.imageUrl}`;
            this.loading = false;
          } else {
            if (game.isLive || !this.funModeAvailable) {
              this.storageService.setItem(`external-game-mode_${this.gameName}`, InstantGameMode.Real);
              this.mode = InstantGameMode.Real;
            } else {
              this.mode = this.storageService.getItem(`external-game-mode_${this.gameName}`) || InstantGameMode.Demo;
            }

            this.showSwitchMode = this.mode === InstantGameMode.Demo && this.loggedIn;

            if (this.mediaService?.media <= Media.sm) {
              this.height = window.innerHeight - (this.game.navBar ? 65 : 0) - 55 - (this.showSwitchMode ? 57 : 0);
              this.width = 0;
            } else {
              this.width = game.configuration.width;
              this.height = game.configuration.height;
            }

            this.gameUrl =
              game.isLive || (this.mode === InstantGameMode.Real && this.authService.isAuthenticated())
                ? game.configuration.userConnectedUrl
                : game.configuration.userDisconnectedUrl;

            // Force iFrame to reload and raise again the onload event
            if (reloadUrl) {
              this.gameUrl += '';
            }

            this.iframe.nativeElement.contentWindow.location.replace(this.gameUrl);
          }
        } else {
          this.router.navigate([`/${this.instantGamesBetCategoryPath}`]);
        }
      });
  }
}
