import {
  OnInit,
  ChangeDetectionStrategy,
  Component,
  ChangeDetectorRef,
  ElementRef,
  ViewChild,
  OnDestroy
} from '@angular/core';
import { AuthService } from '@honoregaming/customer-core';
import { spinAndWinWheelItems } from '../../constants/spin-and-win-wheel-items';
import { LocalStorageService, DestroySubject, BetCategoryConfigurationService } from '@honoregaming/core';
import { InstantGame, InstantGameMode, InstantGameName } from '@honoregaming/types';
import {
  BettingApiService,
  SpinAndWinItemResultResponse,
  CreateInstantGameTransactionResponse,
  BettingError,
  CreateBetFailures
} from '@honoregaming/betslip';
import { takeUntil } from 'rxjs/operators';
import { InstantGameService } from '@honoregaming/events';
import { GenericContentComponent, MessageService } from '@honoregaming/ui';
import { NavBarService } from 'projects/customer/customer/src/app/services';
import { I18nService } from '@honoregaming/i18n';
import { CreateInstantGameTransactionFailure } from 'projects/core/hg-betslip/src/lib/models/create-instantgame-transaction-failre.enum';
import { Router } from '@angular/router';

const casinoSpinAndWinMode = 'casino-spinandwin-mode';

@Component({
  selector: 'hg-spin-and-win-game',
  templateUrl: './spin-and-win-game.component.html',
  styleUrls: ['./spin-and-win-game.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class SpinAndWinGameComponent extends DestroySubject implements OnInit, OnDestroy {
  stakes = 0;
  balance: number;
  loggedIn: boolean;
  paidAmount: number;
  maxAmount: number;
  configSuccess: boolean;
  history: { result: number; winner: boolean; paidAmount: number }[] = [];

  tokens: number[];
  currentToken: number;
  tokenList: { element: HTMLImageElement; case: number; token: number }[] = [];

  betTypes: { [index: number]: number } = { 2: 0, 4: 0, 5: 0, 10: 0, 20: 0, 40: 0 };
  savedBetSlip: { element: HTMLImageElement; case: number; token: number }[] = [];

  loading = false;
  gameInProgress = false;
  gameMode = InstantGameMode;
  mode: InstantGameMode;
  toggleRules = false;
  result: CreateInstantGameTransactionResponse;
  wheelItems: number[] = [];
  resultAngle = 0;

  @ViewChild('wheel') wheelElementRef: ElementRef;
  @ViewChild('popup') popupElementRef: ElementRef;
  @ViewChild('tick') tickElementRef: ElementRef;

  instantGamesBetCategoryPath = this.betCategoryConfigurationService.getInstantGamesBetCategoryPath();

  constructor(
    private instantGameService: InstantGameService,
    private bettinApiService: BettingApiService,
    private cdRef: ChangeDetectorRef,
    private router: Router,
    private authService: AuthService,
    private storageService: LocalStorageService,
    private messageService: MessageService,
    private navBarService: NavBarService,
    private i18nService: I18nService,
    private betCategoryConfigurationService: BetCategoryConfigurationService
  ) {
    super();
  }

  ngOnInit() {
    this.loading = true;
    this.wheelItems = spinAndWinWheelItems;

    this.authService.me$.pipe(takeUntil(this.destroy$)).subscribe(me => {
      if (me) {
        this.loggedIn = true;
        this.balance = me.balance;
        this.reset();
      } else {
        this.loggedIn = false;
      }
      this.cdRef.markForCheck();
    });
    this.mode = this.storageService.getItem(casinoSpinAndWinMode) || InstantGameMode.Demo;

    this.instantGameService
      .getInstantGames()
      .pipe(takeUntil(this.destroy$))
      .subscribe((gamesList: InstantGame[]) => {
        const spinAndWin = gamesList
          .filter(g => g.provider.toLowerCase() === 'internal')
          .find(g => g.name === InstantGameName.SpinAndWin);

        if (spinAndWin) {
          this.navBarService.setNavBarActive(spinAndWin.navBar);
        } else {
          this.router.navigate([`/${this.instantGamesBetCategoryPath}`]);
        }

        const configuration = spinAndWin?.configuration;
        if (configuration.maxAmount) {
          this.maxAmount = configuration.maxAmount;
        }

        this.configSuccess = JSON.stringify(this.wheelItems) === JSON.stringify(configuration.spinAndWinConfiguration);
        this.tokens = configuration.tokens;
        this.currentToken = this.tokens[0];
        this.loading = false;
        this.cdRef.markForCheck();
      });
  }

  ngOnDestroy() {
    super.ngOnDestroy();
    this.navBarService.setNavBarActive(true);
  }

  addToken(caseNumber: number, tokenNumber: number = this.currentToken) {
    if (
      this.gameInProgress ||
      (this.loggedIn &&
        (this.stakes + tokenNumber > this.balance ||
          (this.maxAmount && this.stakes + this.currentToken > this.maxAmount)))
    ) {
      return;
    }

    const tokenHolder = document.querySelector('.token-holder' + caseNumber);
    const newTokenImage = document.createElement('img');
    newTokenImage.src = 'assets/instant-games/tokens/' + tokenNumber + '.svg';

    newTokenImage.classList.add('token-placed');
    tokenHolder.appendChild(newTokenImage);

    this.betTypes[caseNumber] = this.betTypes[caseNumber] + tokenNumber;
    this.tokenList.push({
      element: newTokenImage,
      case: caseNumber,
      token: tokenNumber
    });
    this.stakes += tokenNumber;
  }

  start() {
    if (this.stakes > 0 && !this.gameInProgress) {
      this.gameInProgress = true;

      const betslip: { [index: number]: number } = {};
      for (const bt in this.betTypes) {
        if (this.betTypes[bt] > 0) {
          betslip[bt] = this.betTypes[bt];
        }
      }
      this.savedBetSlip = [...this.tokenList];
      this.bettinApiService
        .createInstantGameTransaction({
          instantGameMode: this.loggedIn ? this.mode : InstantGameMode.Demo,
          instantGameName: InstantGameName.SpinAndWin,
          stake: this.stakes,
          selection: betslip
        })
        .pipe(takeUntil(this.destroy$))
        .subscribe(
          response => {
            this.spin(response, (response.result as SpinAndWinItemResultResponse).respins);
          },
          (err: BettingError) => {
            switch (err.failure) {
              case CreateBetFailures.TooManyRequests:
                this.messageService
                  .sendComponentMessage(GenericContentComponent, {
                    text: this.i18nService.translateSync('INSTANT-GAMES.ERRORS.TOO_MANY_REQUESTS')
                  })
                  .closed.subscribe(_ => {
                    this.gameInProgress = false;
                    this.cdRef.markForCheck();
                  });
                break;
              case CreateInstantGameTransactionFailure.CustomerLimitationExceeded:
              case CreateInstantGameTransactionFailure.CustomerSelfExcluded:
                this.messageService
                  .sendComponentMessage(
                    GenericContentComponent,
                    {
                      title: this.i18nService.translateSync('RESPONSIBLE_GAMBLING.SELF_LIMITATION'),
                      text: this.i18nService.translateSync('BET-SLIP.BETTING_ERROR.LIMIT_REACHED')
                    },
                    { canBeDismissed: true, displayClose: true, dark: true }
                  )
                  .closed.subscribe(_ => {
                    this.gameInProgress = false;
                    this.cdRef.markForCheck();
                  });
            }
          }
        );
    }
  }

  spin(response: CreateInstantGameTransactionResponse, round: number) {
    const respinAdditionalAngle = -1080 * (response.result.respins - round);

    if (round > 0) {
      const spinPositions = [1, 12, 25, 36];
      this.resultAngle = -1080 + respinAdditionalAngle + (360 / 49) * spinPositions[Math.round(Math.random() * 3)] * -1;
    } else {
      this.resultAngle = -1080 + respinAdditionalAngle + (360 / 49) * response.result.position * -1;
    }

    this.wheelElementRef.nativeElement.style = 'transform: rotate(' + this.resultAngle + 'deg);';

    if (round > 0) {
      setTimeout(() => {
        this.cdRef.markForCheck();
        this.spin(response, round - 1);
      }, 9000);
    } else {
      // Show result
      setTimeout(() => {
        this.result = response;
        this.paidAmount = response.paidAmount - this.stakes;
        this.cdRef.markForCheck();

        // Hide result
        setTimeout(() => {
          if (this.loggedIn && this.mode === InstantGameMode.Real) {
            if (this.history.length === 4) {
              this.history.pop();
            }
            this.history.unshift({
              result: response.result.number,
              paidAmount: this.paidAmount,
              winner: this.paidAmount >= 0
            });
          }

          this.result = null;
          if (this.loggedIn) {
            this.authService.getBalance().pipe(takeUntil(this.destroy$)).subscribe();
          }
          this.reset();
          this.cdRef.markForCheck();
        }, 2000);
      }, 8000);
    }
  }

  reset() {
    this.gameInProgress = false;
    this.betTypes = { 2: 0, 4: 0, 5: 0, 10: 0, 20: 0, 40: 0 };
    this.stakes = 0;
    this.cdRef.markForCheck();
    while (this.tokenList.length) {
      this.tokenList[this.tokenList.length - 1].element.parentNode.removeChild(
        this.tokenList[this.tokenList.length - 1].element
      );
      this.tokenList.pop();
    }

    if (this.wheelElementRef) {
      const resetAngle = this.resultAngle % 360;
      this.wheelElementRef.nativeElement.style = 'transform: rotate(' + resetAngle + 'deg); transition: all 0s';
    }
  }

  clearAll() {
    if (!this.gameInProgress) {
      this.reset();
    }
  }

  clearLast() {
    if (!this.gameInProgress && this.tokenList.length) {
      this.stakes -= this.tokenList[this.tokenList.length - 1].token;
      this.betTypes[this.tokenList[this.tokenList.length - 1].case] -= this.tokenList[this.tokenList.length - 1].token;
      this.tokenList[this.tokenList.length - 1].element.parentNode.removeChild(
        this.tokenList[this.tokenList.length - 1].element
      );
      this.tokenList.pop();
    }
  }

  replay() {
    if (!this.gameInProgress) {
      this.reset();
      for (const token of this.savedBetSlip) {
        this.addToken(token.case, token.token);
      }
    }
  }

  switchMode() {
    this.storageService.setItem(casinoSpinAndWinMode, InstantGameMode.Real);
    this.mode = InstantGameMode.Real;
    this.cdRef.markForCheck();
  }
}
