import { HttpClient } from '@angular/common/http';
import { Inject, Injectable } from '@angular/core';
import { BehaviorSubject, EMPTY, Observable, combineLatest, merge, of } from 'rxjs';
import { catchError, map, shareReplay, skip, switchMap, take, tap } from 'rxjs/operators';
import { Cacheable } from '@honoregaming/core';
import { globalConfiguration, OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { InstantGame, InstantGameTournament, TournamentFilter } from '@honoregaming/types';
import { AuthService, authServiceToken } from '@honoregaming/authentication';
import { InstantGamesDataService } from './instant-games-data.service';
import { RankedMember, TournamentDetail, TournamentLeaderboard } from '../types/tournament-detail.types';

@Injectable({ providedIn: 'root' })
export class InstantGamesTournamentsService {
  private readonly loadingSubject$ = new BehaviorSubject<boolean>(false);
  private readonly errorSubject$ = new BehaviorSubject<string | null>(null);
  private readonly refreshSubject$ = new BehaviorSubject<void>(undefined);

  readonly loading$: Observable<boolean> = this.loadingSubject$.asObservable();
  readonly error$: Observable<string | null> = this.errorSubject$.asObservable();

  readonly tournaments$: Observable<InstantGameTournament[]>;

  constructor(
    private readonly httpClient: HttpClient,
    private readonly instantGamesDataService: InstantGamesDataService,
    @Inject(authServiceToken) authService: AuthService,
    @Inject(operatorConfigurationToken) private readonly operatorConfiguration: OperatorConfiguration
  ) {
    const authRefresh$: Observable<void> = authService.status$.pipe(
      skip(1),
      map(() => undefined as void)
    );

    this.tournaments$ = merge(this.refreshSubject$, authRefresh$).pipe(
      switchMap(() => this.fetchTournaments()),
      shareReplay(1)
    );
  }

  getTournamentsByStatus(filter: TournamentFilter): Observable<InstantGameTournament[]> {
    const statusOrder: Record<string, number> = { Ongoing: 0, Upcoming: 1, Finished: 2 };
    return this.tournaments$.pipe(
      map((tournaments: InstantGameTournament[]) => {
        if (filter !== 'ALL') {
          return tournaments.filter(tournament => tournament.status === filter);
        }
        return [...tournaments].sort((a, b) => (statusOrder[a.status] ?? 0) - (statusOrder[b.status] ?? 0));
      })
    );
  }

  refresh(): void {
    this.refreshSubject$.next();
  }

  optIn(tournamentId: string): Observable<void> {
    return this.httpClient
      .post<void>(globalConfiguration.apiBaseUrl + `tournaments/${tournamentId}/optin`, {})
      .pipe(tap(() => this.refreshSubject$.next()));
  }

  getTournamentDetail(id: string): Observable<TournamentDetail> {
    return combineLatest([
      this.httpClient.get<TournamentDetail>(globalConfiguration.apiBaseUrl + `tournaments/${id}`),
      this.tournaments$.pipe(
        take(1),
        map(tournaments => tournaments.find(tournament => tournament.id.toString() === id))
      )
    ]).pipe(
      map(([detail, tournament]) => ({
        ...detail,
        instantGames: (detail.instantGames ?? []).map(game => this.instantGamesDataService.mapGame(game)),
        prizePool: tournament?.prizePool,
        freeSpinsCount: tournament?.freeSpinsCount,
        itemsCount: tournament?.itemsCount,
        customerRanking: tournament?.customerRanking,
        customerScore: tournament?.customerScore
      })),
      catchError(error => {
        this.errorSubject$.next(error.message);
        return EMPTY;
      })
    );
  }

  @Cacheable()
  getTournamentInstantGames(id: string): Observable<InstantGame[]> {
    return this.httpClient.get<InstantGame[]>(globalConfiguration.apiBaseUrl + `tournaments/${id}/instant-games`).pipe(
      map(games => games.map(game => this.instantGamesDataService.mapGame(game))),
      catchError(error => {
        this.errorSubject$.next(error.message);
        return EMPTY;
      })
    );
  }

  getTournamentLeaderboard(id: string): Observable<TournamentLeaderboard> {
    return this.httpClient
      .get<TournamentLeaderboard>(globalConfiguration.apiBaseUrl + `tournaments/${id}/leaderboard`)
      .pipe(
        map(leaderboard => {
          const topPositions = new Set(
            leaderboard.topRankedMembers?.map((member: RankedMember) => member.position) ?? []
          );
          return {
            ...leaderboard,
            topRankedMembers: (leaderboard.topRankedMembers ?? []).filter(
              (member: RankedMember) => member.position > 0
            ),
            playerAndAdjacentRankedMembers: (leaderboard.playerAndAdjacentRankedMembers ?? []).filter(
              (member: RankedMember) => !topPositions.has(member.position) && member.position > 0
            ),
            bottomRankedMembers: (leaderboard.bottomRankedMembers ?? []).filter(
              (member: RankedMember) => member.position > 0
            )
          };
        }),
        catchError(error => {
          this.errorSubject$.next(error.message);
          return EMPTY;
        })
      );
  }

  private fetchTournaments(): Observable<InstantGameTournament[]> {
    if (!this.operatorConfiguration.operatorFeatures?.includes('Tournament')) {
      return of([]);
    }
    this.loadingSubject$.next(true);
    const params = { withAllTournaments: true };
    return this.httpClient
      .get<InstantGameTournament[]>(globalConfiguration.apiBaseUrl + `tournaments`, { params })
      .pipe(
        map(tournaments =>
          tournaments
            .filter(tournament => !tournament.isCustomerBlacklisted)
            .map(tournament => ({
              ...tournament,
              instantGames: (tournament.instantGames ?? []).map(game => this.instantGamesDataService.mapGame(game))
            }))
        ),
        tap(() => this.loadingSubject$.next(false)),
        catchError(error => {
          this.errorSubject$.next(error.message);
          this.loadingSubject$.next(false);
          return EMPTY;
        })
      );
  }
}
