import { Routes, RouterModule } from '@angular/router';
import { NgModule } from '@angular/core';
import { InstantGamesHomeComponent } from './containers/instant-games-home/instant-games-home.component';
import { SpinAndWinGameComponent } from './containers/spin-and-win/spin-and-win-game.component';
import { RouletteGameComponent } from './containers/roulette-game/roulette-game.component';
import { PenaltyGameComponent } from './containers/penalty/penalty-game.component';
import { MusikaComponent } from './containers/musika/musika.component';
import { InsaGamesComponent } from './containers/insa-games/insa-games.component';
import { EmGameComponent } from './containers/em-game/em-game.component';
import { LayoutComponent } from './containers/layout/layout.component';
import { GtGameComponent } from './containers/gt-game/gt-game.component';
import { AviatorLlcGameComponent } from './containers/aviator-llc-game/aviator-llc-game.component';
import { InstantGamesListComponent } from './component/instant-games-list/instant-games-list.component';
import { BgGameComponent } from './containers/bg-game/bg-game.component';
import { InstantGamesTournamentsListComponent } from './component/tournaments/instant-games-tournaments-list/instant-games-tournaments-list.component';
import { InstantGamesTournamentDetailComponent } from './component/tournaments/instant-games-tournament-detail/instant-games-tournament-detail.component';
import { InstantGamesTournamentGamesComponent } from './component/tournaments/instant-games-tournament-games/instant-games-tournament-games.component';

const routes: Routes = [
  {
    path: '',
    component: LayoutComponent,
    children: [
      {
        path: '',
        component: InstantGamesHomeComponent
      },
      {
        path: 'roulette',
        component: RouletteGameComponent,
        data: { 'sidebar-content': 'none' }
      },
      {
        path: 'spin-and-win',
        component: SpinAndWinGameComponent,
        data: { 'sidebar-content': 'none' }
      },
      {
        path: 'penalty',
        component: PenaltyGameComponent,
        data: { 'sidebar-content': 'none' }
      },
      {
        path: 'musika',
        component: MusikaComponent,
        data: { 'sidebar-content': 'none' }
      },
      {
        path: 'em/:slug',
        component: EmGameComponent,
        data: { 'sidebar-content': 'none' }
      },
      {
        path: 'ig/:gameRef',
        component: InsaGamesComponent,
        data: { 'sidebar-content': 'none' }
      },
      {
        path: 'gt/:gameName',
        component: GtGameComponent,
        data: { 'sidebar-content': 'none' }
      },
      {
        path: 'llc/:gameName',
        component: AviatorLlcGameComponent,
        data: { 'sidebar-content': 'none' }
      },
      {
        path: 'bg/:slug',
        component: BgGameComponent,
        data: { 'sidebar-content': 'none' }
      },
      { path: 'category/:categoryId', component: InstantGamesListComponent },
      { path: 'category/:categoryId/:vendorName', component: InstantGamesListComponent },
      { path: 'provider/:vendorName', component: InstantGamesListComponent },
      { path: 'tournaments', component: InstantGamesTournamentsListComponent },
      { path: 'tournaments/:id', component: InstantGamesTournamentDetailComponent },
      { path: 'tournaments/:id/games', component: InstantGamesTournamentGamesComponent }
    ]
  }
];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule]
})
export class HgInstantGamesRoutingModule {}
