import { Injectable } from '@angular/core';
import { BehaviorSubject, combineLatest, Observable } from 'rxjs';
import { map, take, tap } from 'rxjs/operators';
import { InstantGame, Vendor } from '@honoregaming/types';
import { InstantGameService } from '@honoregaming/events';
import { FavoriteManagerService } from 'projects/customer/hg-core/src/lib/services/domain/favorite-manager.service';
import { InstantGamesDataService } from './instant-games-data.service';
import { InstantGamesCategoriesService } from './instant-games-categories.service';

@Injectable({ providedIn: 'root' })
export class InstantGamesFiltersService {
  private readonly filteredGamesSubject$ = new BehaviorSubject<InstantGame[]>([]);
  filteredGames$: Observable<InstantGame[]> = this.filteredGamesSubject$.asObservable();
  private readonly filteredVendorsSubject$ = new BehaviorSubject<Vendor[]>([]);
  filteredVendors$: Observable<Vendor[]> = this.filteredVendorsSubject$.asObservable();

  constructor(
    private readonly instantGamesDataService: InstantGamesDataService,
    private readonly favoriteManagerService: FavoriteManagerService,
    private readonly instantGameService: InstantGameService,
    private readonly categoriesService: InstantGamesCategoriesService
  ) {}

  // --- FILTER GAME ---

  get favoritesIds$(): Observable<number[]> {
    return this.favoriteManagerService.favorites$.pipe(map(favs => favs?.map(fav => fav.id) ?? []));
  }

  searchInstantGamesAndVendors(
    searchText: string
  ): Observable<[{ instantGames: InstantGame[]; vendors: Vendor[] }, number[], Record<number, number>]> {
    return combineLatest([
      this.instantGameService.searchInstantGamesVendors(searchText).pipe(take(1)),
      this.favoritesIds$,
      this.instantGamesDataService.rawCustomersInPlay$
    ]).pipe(
      tap(([result, favoritesIds, customers]) => {
        const favoritesSet: Set<number> = new Set(favoritesIds);
        const mappedGames: InstantGame[] = result.instantGames.map(game =>
          this.instantGamesDataService.mapGame(game, favoritesSet, customers)
        );
        this.filteredGamesSubject$.next(mappedGames);
        const vendors: Vendor[] = result.vendors.map(vendor => ({
          ...vendor,
          imageUrl: this.categoriesService.getVendorImageUrl(vendor.name)
        }));

        this.filteredVendorsSubject$.next(vendors);
      })
    );
  }

  resetFilters(): void {
    this.filteredGamesSubject$.next([]);
    this.filteredVendorsSubject$.next([]);
  }
}
