import { Router } from '@angular/router';
import { Component, ChangeDetectionStrategy, Inject, Input, Optional } from '@angular/core';
import { interval, Observable } from 'rxjs';
import { distinctUntilChanged, map, startWith, take, takeWhile } from 'rxjs/operators';
import { InstantGame, InstantGameTournament, TournamentStatus } from '@honoregaming/types';
import { TelemetryService } from '@honoregaming/customer-core';
import { DialogService } from '@honoregaming/core';
import { GenericContentComponent, Media, MediaService, MessageService, ToasterService } from '@honoregaming/ui';
import { AuthService, authServiceToken } from '@honoregaming/authentication';
import { I18nService } from 'projects/core/hg-i18n/src/lib/services/i18n.service';
import { InstantGamesDataService } from '../../../services/instant-games-data.service';
import { InstantGamesRouteService } from '../../../services/instant-games-route.service';
import { InstantGamesTournamentsService } from '../../../services/instant-games-tournaments.service';
import { CountdownUnit } from '../../../types/tournament-detail.types';
import { computeCountdown } from '../../../utils/tournament.utils';

@Component({
  selector: 'hg-instant-games-tournament-card',
  templateUrl: './instant-games-tournament-card.component.html',
  styleUrls: ['./instant-games-tournament-card.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class InstantGamesTournamentCardComponent {
  @Input() tournament!: InstantGameTournament;
  @Input() miniMode: boolean = false;
  @Input() desktopMode: boolean = false;
  @Input() alone: boolean = false;
  @Input() mouseMove: boolean = false;

  isOnAll$: Observable<boolean>;
  readonly isAuthenticated$: Observable<boolean> = this.authService.status$.pipe(
    startWith(null),
    map(() => this.authService.isAuthenticated()),
    distinctUntilChanged()
  );
  private optInSuccessMsg: string = '';
  readonly countdown$: Observable<CountdownUnit[]> = interval(1000).pipe(
    startWith(0),
    map(() => computeCountdown(this.tournament.endDate)),
    takeWhile(units => units.some(unit => unit.value !== '00'), true)
  );

  readonly TournamentStatus = TournamentStatus;

  constructor(
    public readonly instantGamesDataService: InstantGamesDataService,
    public readonly instantGamesRouteService: InstantGamesRouteService,
    public readonly router: Router,
    public readonly telemetryService: TelemetryService,
    private readonly tournamentsService: InstantGamesTournamentsService,
    private readonly toasterService: ToasterService,
    private readonly i18nService: I18nService,
    private readonly dialogService: DialogService,
    private readonly messageService: MessageService,
    @Inject(authServiceToken) private readonly authService: AuthService,
    @Optional() private readonly mediaService: MediaService
  ) {
    this.isOnAll$ = this.instantGamesRouteService.isOnAll$;
    this.i18nService
      .translate('INSTANT-GAMES.TOURNAMENTS.OPTIN_SUCCESS')
      .pipe(take(1))
      .subscribe(msg => (this.optInSuccessMsg = msg));
  }

  get gamesToShow() {
    const games: InstantGame[] = this.tournament?.instantGames ?? [];
    return games.slice(
      0,
      this.desktopMode ? (games.length <= 2 ? games.length : games.length <= 5 ? 3 : 6) : games.length === 2 ? 2 : 3
    );
  }

  get statusClass() {
    return 'card--' + this.tournament.status.toLowerCase();
  }

  get podiumOrder() {
    return [2, 1, 3].map(position => this.tournament?.podiumMembers?.find(member => member.position === position));
  }

  optIn(tournamentId: number, event: Event): void {
    if (this.mouseMove) {
      event.preventDefault();
      return;
    }
    if (!this.authService.isAuthenticated()) {
      if (this.mediaService?.media >= Media.lg) {
        this.messageService
          .sendComponentMessage(
            GenericContentComponent,
            {
              title: this.i18nService.translateSync('COMMON.LOGIN_REQUIRED'),
              text: this.i18nService.translateSync('INSTANT-GAMES.TOURNAMENTS.LOGIN_REQUIRED'),
              okButton: true,
              okButtonTranslationKey: 'COMMON.I_GET_IT'
            } as any,
            { canBeDismissed: true, displayClose: true, className: 'popin-tournament-optin' }
          )
          .closed.subscribe(confirmed => {
            if (confirmed) this.dialogService.toggleDialog('login', true);
          });
      } else {
        this.dialogService.toggleDialog('login', true);
      }
      return;
    }
    this.tournamentsService
      .optIn(tournamentId.toString())
      .pipe(take(1))
      .subscribe({
        next: () => this.toasterService.show({ text: this.optInSuccessMsg, type: 'add', id: 'Tournament_OptIn_Notif' }),
        error: err => console.error('optIn error', err)
      });
  }

  gameClicked(gameName: string): void {
    this.telemetryService.trackEvent('casino_game_click', { game_name: gameName });
  }

  trackByGame(_index: number, item: { id: number }): number {
    return item.id;
  }
}
