import { isPlatformServer } from '@angular/common';
import { Component, ChangeDetectionStrategy, Inject, PLATFORM_ID, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { switchMap, takeUntil } from 'rxjs/operators';
import { AuthService } from '@honoregaming/customer-core';
import { BetCategoryConfigurationService, DestroySubject } from '@honoregaming/core';
import { FavoriteManagerService } from 'projects/customer/hg-core/src/lib/services/domain/favorite-manager.service';
import { EMPTY } from 'rxjs';

@Component({
  selector: 'hg-layout',
  templateUrl: './layout.component.html',
  styleUrls: ['./layout.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class LayoutComponent extends DestroySubject implements OnInit {
  isServer = isPlatformServer(this.platformId);
  instantGamesBetCategoryPath: string = this.betCategoryConfigurationService.getInstantGamesBetCategoryPath();

  constructor(
    private readonly authService: AuthService,
    public readonly router: Router,
    public readonly betCategoryConfigurationService: BetCategoryConfigurationService,
    private readonly favoriteManagerService: FavoriteManagerService,
    @Inject(PLATFORM_ID) private readonly platformId: Object
  ) {
    super();
  }

  ngOnInit(): void {
    this.authService.status$
      .pipe(
        switchMap(status => {
          if (status === 'connected') {
            return this.favoriteManagerService.loadFavorites();
          } else {
            this.favoriteManagerService.clearFavorites();
            return EMPTY;
          }
        }),
        takeUntil(this.destroy$)
      )
      .subscribe();
  }
}
