import { Component, ChangeDetectionStrategy, Optional } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { combineLatest, Observable, of } from 'rxjs';
import { map, switchMap, take } from 'rxjs/operators';
import { Media, MediaService } from '@honoregaming/ui';
import { InstantGame } from '@honoregaming/types';
import { FavoriteManagerService } from 'projects/customer/hg-core/src/lib/services/domain/favorite-manager.service';
import { InstantGamesTournamentsService } from '../../../services/instant-games-tournaments.service';

interface GamesViewModel {
  name: string;
  games: InstantGame[];
  isDesktop: boolean;
}

@Component({
  selector: 'hg-instant-games-tournament-games',
  templateUrl: './instant-games-tournament-games.component.html',
  styleUrls: ['./instant-games-tournament-games.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class InstantGamesTournamentGamesComponent {
  readonly gamesViewModel$: Observable<GamesViewModel> = this.route.params.pipe(
    switchMap(({ id }) =>
      combineLatest([
        this.tournamentsService.getTournamentDetail(id as string),
        this.tournamentsService.getTournamentInstantGames(id as string),
        this.mediaService ? this.mediaService.media$.pipe(map(media => media >= Media.lg)) : of(false),
        this.favoriteManagerService.favorites$.pipe(map(favs => new Set(favs.map(game => game.id))))
      ])
    ),
    map(([detail, games, isDesktop, favoriteIds]) => ({
      name: detail.name,
      isDesktop,
      games: games.map(game => ({ ...game, isFavorite: favoriteIds.has(game.id) }))
    }))
  );

  constructor(
    private readonly route: ActivatedRoute,
    private readonly tournamentsService: InstantGamesTournamentsService,
    public readonly favoriteManagerService: FavoriteManagerService,
    @Optional() private readonly mediaService: MediaService
  ) {}

  toggleFavorite(game: InstantGame, event: Event): void {
    event.stopPropagation();
    event.preventDefault();
    this.favoriteManagerService.toggle(game).pipe(take(1)).subscribe();
  }

  trackByGame(_index: number, game: InstantGame): number {
    return game.id;
  }
}
