import {
  Component,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Input,
  OnDestroy,
  Renderer2,
  Inject
} from '@angular/core';
import { BehaviorSubject, EMPTY, Observable, Subject, combineLatest, forkJoin, interval, of, timer } from 'rxjs';
import {
  catchError,
  distinctUntilChanged,
  filter,
  map,
  pairwise,
  shareReplay,
  startWith,
  switchMap,
  take,
  takeUntil
} from 'rxjs/operators';
import { InstantGameTournament } from '@honoregaming/types';
import {
  RankedMember,
  RewardCard,
  TournamentDetail,
  TournamentLeaderboard,
  TournamentPrize
} from '../../../types/tournament-detail.types';
import { computeCountdown } from '../../../utils/tournament.utils';
import { AuthService, authServiceToken } from '@honoregaming/authentication';
import { InstantGamesTournamentsService } from '../../../services/instant-games-tournaments.service';

@Component({
  selector: 'hg-instant-games-in-game-tournament-banner',
  templateUrl: './instant-games-in-game-tournament-banner.component.html',
  styleUrls: ['./instant-games-in-game-tournament-banner.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class InstantGamesInGameTournamentBannerComponent implements OnDestroy {
  @Input() set gameId(id: number) {
    this.gameId$.next(id);
  }

  showPopin: boolean = false;
  tournamentDetail: TournamentDetail | null = null;
  rewardCards: RewardCard[] = [];
  hasLeaderboard: boolean = false;
  activeTab: 'rules' | 'ranking' | 'rewards' = 'rules';

  private readonly gameId$ = new BehaviorSubject<number | null>(null);
  private readonly showPopin$ = new BehaviorSubject<boolean>(false);
  private readonly leaderboardRefresh$ = new Subject<void>();
  private readonly destroy$ = new Subject<void>();

  readonly activeTournament$: Observable<InstantGameTournament | null> = combineLatest([
    this.tournamentsService.tournaments$,
    this.gameId$.pipe(filter((gameId): gameId is number => gameId !== null)),
    this.authService.status$
  ]).pipe(
    switchMap(([tournaments, gameId, status]) => {
      if (status !== 'connected') return of(null);

      const ongoingParticipating: InstantGameTournament[] = tournaments.filter(
        (tournament: InstantGameTournament) =>
          tournament.status === 'Ongoing' && (tournament.isCustomerAlreadyParticipating || !tournament.isOptInNecessary)
      );

      if (ongoingParticipating.length === 0) return of(null);

      const fromPreview: InstantGameTournament | null =
        ongoingParticipating.find(tournament => tournament.instantGames?.some(game => game.id === gameId)) ?? null;
      if (fromPreview) return of(fromPreview);

      return forkJoin(
        ongoingParticipating.map(tournament =>
          this.tournamentsService.getTournamentInstantGames(tournament.id.toString()).pipe(
            map(games => (games.some(game => game.id === gameId) ? tournament : null)),
            catchError(() => of(null))
          )
        )
      ).pipe(map(results => results.find(Boolean) ?? null));
    }),
    shareReplay(1)
  );

  readonly rankChange$: Observable<{ delta: number; direction: 'up' | 'down' } | null> = this.activeTournament$.pipe(
    pairwise(),
    switchMap(([prev, curr]) => {
      if (!prev || !curr || prev.customerRanking === curr.customerRanking) return of(null);
      const delta: number = prev.customerRanking - curr.customerRanking;
      const change = { delta: Math.abs(delta), direction: (delta > 0 ? 'up' : 'down') as 'up' | 'down' };
      return of(change).pipe(
        switchMap(rankChange =>
          timer(3000).pipe(
            map(() => null),
            startWith(rankChange)
          )
        )
      );
    }),
    startWith(null)
  );

  readonly leaderboard$: Observable<TournamentLeaderboard | null> = combineLatest([
    this.showPopin$,
    this.activeTournament$,
    this.leaderboardRefresh$.pipe(startWith(undefined as void))
  ]).pipe(
    switchMap(([isOpen, tournament]) =>
      isOpen && tournament ? this.tournamentsService.getTournamentLeaderboard(tournament.id.toString()) : of(null)
    ),
    startWith(null),
    shareReplay(1)
  );

  readonly countdown$: Observable<string> = this.activeTournament$.pipe(
    distinctUntilChanged((prev, curr) => prev?.endDate === curr?.endDate),
    switchMap(tournament =>
      tournament
        ? interval(1000).pipe(
            startWith(0),
            map(() =>
              computeCountdown(tournament.endDate)
                .map(unit => unit.value)
                .join(':')
            )
          )
        : EMPTY
    )
  );

  constructor(
    private readonly tournamentsService: InstantGamesTournamentsService,
    private readonly cdRef: ChangeDetectorRef,
    private readonly renderer: Renderer2,
    @Inject(authServiceToken) private readonly authService: AuthService
  ) {
    this.leaderboard$.pipe(takeUntil(this.destroy$)).subscribe(leaderboard => {
      this.hasLeaderboard = !!leaderboard?.topRankedMembers.some(member => member.score > 0);
      if (leaderboard !== null && !this.hasLeaderboard && this.activeTab === 'ranking') {
        this.activeTab = this.tournamentDetail?.prizes?.length ? 'rewards' : 'rules';
      }
      this.cdRef.markForCheck();
    });

    this.activeTournament$
      .pipe(
        map(tournament => tournament !== null),
        distinctUntilChanged(),
        switchMap(hasActive => (hasActive ? interval(30000) : EMPTY)),
        takeUntil(this.destroy$)
      )
      .subscribe(() => {
        this.tournamentsService.refresh();
        if (this.showPopin) this.leaderboardRefresh$.next();
      });
  }

  ngOnDestroy(): void {
    this.renderer.removeStyle(document.body, 'overflow');
    this.destroy$.next();
    this.destroy$.complete();
  }

  openPopin(tournamentId: number): void {
    this.showPopin = true;
    this.showPopin$.next(true);
    this.renderer.setStyle(document.body, 'overflow', 'hidden');
    if (!this.tournamentDetail) {
      this.tournamentsService
        .getTournamentDetail(tournamentId.toString())
        .pipe(take(1), takeUntil(this.destroy$))
        .subscribe(detail => {
          this.tournamentDetail = detail;
          this.rewardCards = this.groupPrizesByPosition(detail.prizes ?? []);
          if (!detail.rules) {
            this.activeTab = 'ranking';
          }
          this.cdRef.markForCheck();
        });
    }
    this.cdRef.markForCheck();
  }

  closePopin(): void {
    this.showPopin = false;
    this.showPopin$.next(false);
    this.renderer.removeStyle(document.body, 'overflow');
    this.cdRef.markForCheck();
  }

  setTab(tab: 'rules' | 'ranking' | 'rewards'): void {
    this.activeTab = tab;
    this.cdRef.markForCheck();
  }

  trackByPosition(_index: number, member: RankedMember): number {
    return member.position;
  }

  trackByCard(_index: number, card: RewardCard): number {
    return card.fromPosition;
  }

  private groupPrizesByPosition(prizes: TournamentPrize[]): RewardCard[] {
    const cardMap = new Map<string, RewardCard>();
    for (const prize of prizes) {
      const key: string = `${prize.fromPosition}-${prize.toPosition}`;
      if (!cardMap.has(key)) {
        cardMap.set(key, {
          fromPosition: prize.fromPosition,
          toPosition: prize.toPosition,
          cashPrize: null,
          freeSpinPrize: null
        });
      }
      const card: RewardCard = cardMap.get(key)!;
      if (prize.rewardType === 'Cash') {
        card.cashPrize = prize;
      } else if (prize.rewardType === 'FreeSpin') {
        card.freeSpinPrize = prize;
      }
    }
    return Array.from(cardMap.values());
  }
}
