import {
  Component,
  ChangeDetectionStrategy,
  Input,
  ChangeDetectorRef,
  ViewChild,
  ElementRef,
  AfterViewInit,
  OnInit
} from '@angular/core';
import { Router } from '@angular/router';
import { takeUntil } from 'rxjs/operators';
import { InstantGameCategory, InstantGameWinnersStream } from '@honoregaming/types';
import { BetCategoryConfigurationService } from '@honoregaming/core';
import { TelemetryService } from '@honoregaming/customer-core';
import { Media, MediaService } from '@honoregaming/ui';
import { FavoriteManagerService } from 'projects/customer/hg-core/src/lib/services/domain/favorite-manager.service';
import { InstantGamesDataService } from '../../../services/instant-games-data.service';
import { CasinoTrackingService } from '../../../services/casino-tracking.service';
import { InstantGameCategoryComponentBase } from '../instant-game-category.component.base';

@Component({
  selector: 'hg-instant-game-winners-stream-category',
  templateUrl: './instant-game-winners-stream-category.component.html',
  styleUrls: ['./instant-game-winners-stream-category.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class InstantGameWinnersStreamCategoryComponent
  extends InstantGameCategoryComponentBase
  implements OnInit, AfterViewInit
{
  @Input() category?: InstantGameCategory;
  @Input() winnersStream: InstantGameWinnersStream[] = [];

  @ViewChild('scrollContainer', { static: true }) scrollContainer?: ElementRef<HTMLElement>;

  readonly ITEM_WIDTH: number = 130;
  readonly GAP: number = 10;

  repeatedItems: InstantGameWinnersStream[] = [];
  scrollDuration: string = '0s';
  media?: Media;

  constructor(
    private readonly mediaService: MediaService,
    public readonly betCategoryConfigurationService: BetCategoryConfigurationService,
    public readonly cdRef: ChangeDetectorRef,
    public readonly favoriteManagerService: FavoriteManagerService,
    public readonly router: Router,
    public readonly telemetryService: TelemetryService,
    protected readonly instantGamesDataService: InstantGamesDataService,
    public readonly casinoTrackingService: CasinoTrackingService
  ) {
    super(
      betCategoryConfigurationService,
      cdRef,
      instantGamesDataService,
      favoriteManagerService,
      router,
      telemetryService,
      casinoTrackingService
    );
  }

  ngOnInit(): void {
    this.mediaService.media$.pipe(takeUntil(this.destroy$)).subscribe(media => {
      this.media = media;
      this.buildScroll();
    });
  }

  ngAfterViewInit(): void {
    this.buildScroll();
  }

  private get scrollSpeed(): number {
    if (this.media === undefined) return 20;
    return this.media < Media.md ? 30 : 20;
  }

  trackBySlot(index: number, item: InstantGameWinnersStream): string {
    return `${index}-${item.instantGame.id}`;
  }

  private buildScroll(): void {
    if (!this.winnersStream?.length) return;

    const container: HTMLElement | undefined = this.scrollContainer?.nativeElement;
    if (!container) return;

    const slotWidth: number = this.ITEM_WIDTH + this.GAP;
    const containerWidth: number = container.clientWidth;
    const oneOriginalSetWidth: number = this.winnersStream.length * slotWidth;
    const minItemsToFill: number = Math.ceil(containerWidth / slotWidth) + 1;
    const setsNeeded: number = Math.ceil(minItemsToFill / this.winnersStream.length);
    const repeats: number = Math.max(2, setsNeeded + 1);

    this.repeatedItems = Array.from(
      { length: repeats * this.winnersStream.length },
      (_, i) => this.winnersStream[i % this.winnersStream.length]
    );
    this.scrollDuration = `${oneOriginalSetWidth / this.scrollSpeed}s`;
    this.cdRef.detectChanges();
  }
}
