import { Observable } from 'rxjs';
import { Injectable } from '@angular/core';
import { globalConfiguration } from '@honoregaming/configuration';
import { HttpClient } from '@angular/common/http';

@Injectable({ providedIn: 'root' })
export class InsaGamesService {
  constructor(private httpClient: HttpClient) {}

  generateAuthToken(): Observable<{ token: string; expiresIn: number; expiration: Date }> {
    return this.httpClient.get<{ token: string; expiresIn: number; expiration: Date }>(
      `${globalConfiguration.apiBettingBaseUrl}insagames/token`
    );
  }
}
