import {
  Component,
  ChangeDetectionStrategy,
  Input,
  OnInit,
  ChangeDetectorRef,
  Output,
  EventEmitter
} from '@angular/core';
import { takeUntil } from 'rxjs/operators';
import { DestroySubject } from '@honoregaming/core';
import { AuthService } from '@honoregaming/customer-core';

@Component({
  selector: 'hg-favorite',
  templateUrl: './favorite.component.html',
  styleUrls: ['./favorite.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class FavoriteComponent extends DestroySubject implements OnInit {
  @Input() isFavorite: boolean = false;
  @Input() size: number = 24;
  @Input() isDisplayed: boolean = false;

  @Output() favoriteToggled = new EventEmitter<Event>();

  isAuthenticated: boolean = false;

  constructor(private readonly authService: AuthService, private readonly cdRef: ChangeDetectorRef) {
    super();
  }

  public ngOnInit(): void {
    this.authService.status$.pipe(takeUntil(this.destroy$)).subscribe(status => {
      this.isAuthenticated = status === 'connected';

      this.cdRef.markForCheck();
    });
  }

  onToggle(event: Event): void {
    event.stopPropagation();
    this.favoriteToggled.emit(event);
  }

  stop(event: Event): void {
    event.stopPropagation();
  }
}
