import { animate, style, transition, trigger } from '@angular/animations';
import {
  Component,
  ChangeDetectionStrategy,
  Input,
  ChangeDetectorRef,
  ElementRef,
  ViewChild,
  AfterViewInit,
  Inject,
  HostBinding
} from '@angular/core';
import { DOCUMENT } from '@angular/common';
import { Router } from '@angular/router';
import { Observable, of } from 'rxjs';
import { map, take, takeUntil } from 'rxjs/operators';
import { BetCategoryConfigurationService, DestroySubject } from '@honoregaming/core';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { TelemetryService } from '@honoregaming/customer-core';
import { InstantGame, InstantGameCategory, InstantGameCategoryType, Vendor } from '@honoregaming/types';
import { FavoriteManagerService } from 'projects/customer/hg-core/src/lib/services/domain/favorite-manager.service';
import { InstantGamesRouteService } from '../../services/instant-games-route.service';
import { InstantGamesCategoriesService } from '../../services/instant-games-categories.service';
import { InstantGamesFiltersService } from '../../services/instant-games-filters.service';
import { InstantGamesDataService } from '../../services/instant-games-data.service';
import { CasinoTrackingService } from '../../services/casino-tracking.service';
import { CasinoMobileCategoryNavType, CasinoTrackedCategory } from '../../types/casino-tracking.types';

@Component({
  selector: 'hg-instant-games-mobile-header',
  templateUrl: './instant-games-mobile-header.component.html',
  styleUrls: ['./instant-games-mobile-header.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  animations: [
    trigger('slideDownUp', [
      transition(':enter', [style({ height: 0 }), animate(100)]),
      transition(':leave', [animate(100, style({ height: 0 }))])
    ])
  ]
})
export class InstantGamesMobileHeaderComponent extends DestroySubject implements AfterViewInit {
  @Input() displayBetCategoryNameOnMobile: boolean = false;

  @ViewChild('menu') menu!: ElementRef;

  popinSearchIsOpened: boolean = false;
  popinCategoriesIsOpened: boolean = false;
  InstantGameCategoryType = InstantGameCategoryType;
  popinSearchText: string | null = '';
  popinInputUsed: boolean = false;
  isAppBannerDisplayed: boolean = !JSON.parse(localStorage.getItem('appBannerDisplay'));
  categories$: Observable<InstantGameCategory[]> = this.categoriesService.mappedCategories$;
  providersCategoryId$: Observable<number | null> = this.instantGamesDataService.providersCategoryId$;
  activeCategoryId$: Observable<string | null> = this.instantGamesRouteService.activeCategoryId$;
  filteredGames$: Observable<InstantGame[]> = this.instantGamesFiltersService.filteredGames$;
  filteredVendors$: Observable<Vendor[]> = this.instantGamesFiltersService.filteredVendors$;
  categoryFavorites$: Observable<InstantGameCategory | null> = this.findCategoryByType(
    InstantGameCategoryType.Favorites
  );
  categoryTournaments$: Observable<InstantGameCategory | null> = this.findCategoryByType(
    InstantGameCategoryType.Tournaments
  );
  categoryFavoritesId$: Observable<number | null> = this.categoryFavorites$.pipe(
    map((category: InstantGameCategory | null) => category?.id ?? null)
  );
  categoryFavoritesName$: Observable<string | null> = this.categoryFavorites$.pipe(
    map((category: InstantGameCategory | null) => category?.name ?? null)
  );

  categoryFavoritesIconUrl$: Observable<string | null> = this.categoryFavorites$.pipe(
    map((category: InstantGameCategory | null) => category?.iconUrl ?? null)
  );

  instantGamesBetCategoryPath: string = this.betCategoryConfigurationService.getInstantGamesBetCategoryPath();
  readonly hasTournaments$ = of(this.operatorConfiguration.operatorFeatures?.includes('Tournament') ?? false);
  popinCategories$: Observable<InstantGameCategory[]> = this.categoriesService.mappedCategories$.pipe(
    map(categories =>
      categories.filter((category: InstantGameCategory) => category.instantGames?.length > 0).slice(0, 2)
    )
  );

  constructor(
    private readonly cdRef: ChangeDetectorRef,
    private readonly instantGamesDataService: InstantGamesDataService,
    private readonly betCategoryConfigurationService: BetCategoryConfigurationService,
    private readonly favoriteManagerService: FavoriteManagerService,
    private readonly router: Router,
    private readonly instantGamesRouteService: InstantGamesRouteService,
    private readonly categoriesService: InstantGamesCategoriesService,
    private readonly instantGamesFiltersService: InstantGamesFiltersService,
    private readonly telemetryService: TelemetryService,
    private readonly casinoTrackingService: CasinoTrackingService,
    @Inject(DOCUMENT) private readonly document: Document,
    @Inject(operatorConfigurationToken) private readonly operatorConfiguration: OperatorConfiguration
  ) {
    super();
  }

  ngAfterViewInit(): void {
    requestAnimationFrame(() => {
      const el: HTMLElement = this.menu.nativeElement;
      const fits: boolean = el.scrollWidth <= el.clientWidth;
      if (fits) {
        el.classList.add('centered');
      }
    });
  }

  get isSticky(): boolean {
    return this.operatorConfiguration.themeCustomizationConfiguration?.fixedCasinoLobbyHeader;
  }

  @HostBinding('class.sticky')
  get isStickyWithoutTitle(): boolean {
    return this.isSticky && !this.displayBetCategoryNameOnMobile;
  }

  @HostBinding('class.sticky--title')
  get isStickyWithTitle(): boolean {
    return this.isSticky && this.displayBetCategoryNameOnMobile;
  }

  closePopin(): void {
    this.popinSearchIsOpened = false;
    this.popinCategoriesIsOpened = false;
    this.popinInputUsed = false;
    this.popinSearchText = null;
    this.instantGamesFiltersService.resetFilters();
    this.releaseBody();
  }

  openPopin(): void {
    this.popinSearchIsOpened = true;
    this.fixBody();
    this.cdRef.markForCheck();
  }

  openCategoriesMenu(): void {
    this.popinCategoriesIsOpened = true;
  }

  onCategoryClick(category: CasinoTrackedCategory, navType: CasinoMobileCategoryNavType): void {
    this.casinoTrackingService.trackMobileNavbarCategorySelect(category, navType);
    this.router.navigate([`/${this.instantGamesBetCategoryPath}/category`, category.id]);
  }

  onFavoritesCategoryClick(): void {
    this.categoryFavorites$.pipe(take(1)).subscribe((category: InstantGameCategory | null) => {
      if (!category) {
        return;
      }

      this.onCategoryClick(category, 'navbar');
    });
  }

  onGameClicked(gameName: string): void {
    this.telemetryService.trackEvent('casino_game_click', { search_term: this.popinSearchText, game_name: gameName });
  }

  onVendorClick(categoryId: number, providerName: string): void {
    this.telemetryService.trackEvent('casino_vendor_click', {
      search_term: this.popinSearchText,
      provider_name: providerName
    });
    this.router.navigate([`/${this.instantGamesBetCategoryPath}/category`, categoryId, providerName]);
  }

  toggleFavorited(game: InstantGame, event: Event, categoryType = InstantGameCategoryType.Classic): void {
    event.stopPropagation();
    event.preventDefault();
    const isFavoriteCategory: boolean = categoryType === InstantGameCategoryType.Favorites;

    this.favoriteManagerService
      .toggle(game, {
        undoContext: isFavoriteCategory,
        undoAction: () => this.toggleFavorited(game, event, categoryType)
      })
      .pipe(takeUntil(this.destroy$))
      .subscribe();
  }

  submitPopinFilters(): void {
    if (this.popinSearchText && this.popinSearchText.trim().length > 0) {
      this.instantGamesFiltersService
        .searchInstantGamesAndVendors(this.popinSearchText)
        .pipe(takeUntil(this.destroy$))
        .subscribe();
      this.popinInputUsed = true;
      return;
    }

    this.instantGamesFiltersService.resetFilters();
    this.popinInputUsed = false;
  }

  trackByCategory = (_: number, category: InstantGameCategory) => category.id;
  trackByGame = (_: number, game: InstantGame) => game.id;
  trackByVendor = (_: number, vendor: Vendor) => vendor.name;

  openTournament(): void {
    this.categoryTournaments$.pipe(take(1)).subscribe((category: InstantGameCategory | null) => {
      const trackedCategory: CasinoTrackedCategory = category ?? {
        id: null,
        name: InstantGameCategoryType.Tournaments
      };

      this.casinoTrackingService.trackMobileNavbarCategorySelect(trackedCategory, 'navbar');
    });

    this.router.navigate([`/${this.instantGamesBetCategoryPath}/tournaments`]);
  }

  private findCategoryByType(type: InstantGameCategoryType): Observable<InstantGameCategory | null> {
    return this.categoriesService.mappedCategories$.pipe(
      map(
        (categories: InstantGameCategory[]) =>
          categories.find((category: InstantGameCategory) => category.type === type) ?? null
      )
    );
  }

  private fixBody(): void {
    this.document.documentElement.classList.add('hidden');
  }

  private releaseBody(): void {
    this.document.documentElement.classList.remove('hidden');
  }
}
