import { Injectable } from '@angular/core';
import { ActivatedRoute, NavigationEnd, Router } from '@angular/router';
import { Observable } from 'rxjs';
import { distinctUntilChanged, filter, map, startWith } from 'rxjs/operators';

@Injectable({ providedIn: 'root' })
export class InstantGamesRouteService {
  constructor(private readonly router: Router, private readonly route: ActivatedRoute) {}

  get isOnAll$(): Observable<boolean> {
    return this.route$.pipe(
      map(route => route.snapshot.routeConfig?.path === ''),
      distinctUntilChanged()
    );
  }

  private readonly route$ = this.router.events.pipe(
    filter(event => event instanceof NavigationEnd),
    startWith(null as NavigationEnd | null),
    map(() => {
      let route: ActivatedRoute = this.route;
      while (route.firstChild) {
        route = route.firstChild;
      }
      return route;
    })
  );

  readonly activeCategoryId$: Observable<string | null> = this.route$.pipe(
    map(route => route.snapshot.paramMap.get('categoryId') ?? null),
    distinctUntilChanged()
  );

  readonly vendorName$: Observable<string | null> = this.route$.pipe(
    map(route => route.snapshot.paramMap.get('vendorName') ?? null),
    distinctUntilChanged()
  );

  readonly activeTournament$: Observable<boolean> = this.route$.pipe(
    map(route => route.snapshot.url.some(segment => segment.path === 'tournaments')),
    distinctUntilChanged()
  );
}
