import { Injectable, Optional } from '@angular/core';
import { combineLatest, Observable } from 'rxjs';
import { distinctUntilChanged, map, shareReplay, startWith } from 'rxjs/operators';
import { Media, MediaService } from '@honoregaming/ui';
import { InstantGame, InstantGameCategory, InstantGameCategoryType, Vendor } from '@honoregaming/types';
import { globalConfiguration } from '@honoregaming/configuration';
import { FavoriteManagerService } from 'projects/customer/hg-core/src/lib/services/domain/favorite-manager.service';
import { InstantGamesDataService } from './instant-games-data.service';
import { InstantGamesRouteService } from './instant-games-route.service';
import { InstantGamesTournamentsService } from './instant-games-tournaments.service';
@Injectable({ providedIn: 'root' })
export class InstantGamesCategoriesService {
  standardCategories: InstantGameCategoryType[] = [
    InstantGameCategoryType.Classic,
    InstantGameCategoryType.Favorites,
    InstantGameCategoryType.MostLiked,
    InstantGameCategoryType.RecentlyAdded,
    InstantGameCategoryType.RecentlyPlayed
  ];

  assetspath?: string;

  constructor(
    private readonly instantGamesDataService: InstantGamesDataService,
    private readonly routeService: InstantGamesRouteService,
    private readonly favoriteManagerService: FavoriteManagerService,
    private readonly tournamentsService: InstantGamesTournamentsService,
    @Optional() public readonly mediaService: MediaService
  ) {
    const regex: RegExp = new RegExp(/^(https?:\/\/[^/]+)/); // Permet de matcher l'url de base
    const matches: RegExpExecArray | null = regex.exec(globalConfiguration.assetsPath);
    this.assetspath = matches ? matches[0] : '';
  }

  public getVendorImageUrl(vendor: string): string {
    return `${this.assetspath}/instant-game-providers/${encodeURIComponent(vendor.toLowerCase())}.png`;
  }

  // --- CATEGORIES ---
  mappedCategories$: Observable<InstantGameCategory[]> = combineLatest([
    this.instantGamesDataService.rawCategories$,
    this.favoriteManagerService.favorites$,
    this.instantGamesDataService.rawRecentlyPlayed$,
    this.instantGamesDataService.rawCustomersInPlay$,
    this.tournamentsService.tournaments$
  ]).pipe(
    map(([categories, favorites, recentlyPlayed, customers, tournaments]) => {
      const favoritesSet: Set<number> = new Set(favorites.map(fav => fav.id));
      const isMobile: boolean = this.mediaService?.media < Media.md;

      return categories.map(category => {
        const miniMode: boolean =
          category.smallThumbnails && isMobile && this.standardCategories.includes(category.type);

        // --- TOURNAMENTS ---
        if (category.type === InstantGameCategoryType.Tournaments) {
          return {
            ...category,
            data: tournaments.filter(tournament => tournament.status !== 'Finished'),
            miniMode: category.miniMode
          };
        }

        // --- FAVORITES ---
        if (category.type === InstantGameCategoryType.Favorites) {
          const mappedFavs: InstantGame[] = favorites
            .map(game => this.instantGamesDataService.mapGame(game, favoritesSet, customers))
            .slice(0, miniMode ? 32 : 16);

          return {
            ...category,
            instantGames: mappedFavs,
            instantGamesNumber: mappedFavs.length,
            miniMode,
            withCounter: this.computeWithCounter(mappedFavs)
          };
        }

        // --- RECENTLY PLAYED ---
        if (category.type === InstantGameCategoryType.RecentlyPlayed) {
          const mappedRecent: InstantGame[] = recentlyPlayed
            .map(game => this.instantGamesDataService.mapGame(game, favoritesSet, customers))
            .slice(0, miniMode ? 32 : 16);

          return {
            ...category,
            instantGames: mappedRecent,
            instantGamesNumber: mappedRecent.length,
            miniMode,
            withCounter: this.computeWithCounter(mappedRecent)
          };
        }

        // --- PROVIDERS ---
        if (category.type === InstantGameCategoryType.Providers) {
          return {
            ...category,
            vendors: this.getVendors(category).slice(0, 16),
            miniMode
          };
        }

        // --- HIGHLIGHT PROVIDER ---
        if (category.type === InstantGameCategoryType.HighlightProvider) {
          const providerName: string = category.data as string;

          const mappedGames: InstantGame[] = (category.instantGames ?? []).map(game =>
            this.instantGamesDataService.mapGame(game, favoritesSet, customers)
          );

          return {
            ...category,
            vendor: {
              name: providerName,
              imageUrl: this.getVendorImageUrl(providerName)
            },
            instantGames: mappedGames,
            instantGamesNumber: mappedGames.length,
            miniMode,
            withCounter: this.computeWithCounter(mappedGames)
          };
        }

        // --- STANDARD ---
        const mappedStandard: InstantGameCategory = this.mapCategoryBase(category, favoritesSet, customers);

        let threshold: number = miniMode ? 32 : 16;

        if (category.type === InstantGameCategoryType.Top10) {
          threshold = 10;
        } else if (category.type === InstantGameCategoryType.Classic && category.hasHighlighted && miniMode) {
          threshold = 29;
        } else if (mappedStandard.instantGames.filter(game => game.highlighted).length % 2 !== 0) {
          threshold = 17;
        }

        const slicedGames: InstantGame[] = mappedStandard.instantGames.slice(0, threshold);
        return {
          ...mappedStandard,
          instantGames: slicedGames,
          instantGamesNumber: category.instantGamesNumber,
          miniMode,
          withCounter: this.computeWithCounter(slicedGames) && this.standardCategories.includes(category.type)
        };
      });
    }),
    shareReplay(1)
  );

  isLoading$: Observable<boolean> = this.mappedCategories$.pipe(
    map(categories => categories.length === 0),
    startWith(true),
    distinctUntilChanged()
  );

  private mapCategoryBase(
    category: InstantGameCategory,
    favoritesSet: Set<number>,
    customers: Record<number, number>
  ): InstantGameCategory {
    const mappedGames: InstantGame[] = (category.instantGames ?? []).map(game =>
      this.instantGamesDataService.mapGame(game, favoritesSet, customers)
    );
    const isMobile: boolean = this.mediaService?.media < Media.md;
    const miniMode: boolean = category.smallThumbnails && isMobile && this.standardCategories.includes(category.type);
    return {
      ...category,
      instantGames: mappedGames,
      instantGamesNumber: category.instantGamesNumber,
      miniMode,
      withCounter: this.computeWithCounter(mappedGames)
    };
  }

  // --- CATEGORY UNIQUE ---
  categoryViewModel$: Observable<InstantGameCategory | null> = (
    combineLatest([
      this.instantGamesDataService.rawCategory$,
      this.routeService.activeCategoryId$,
      this.routeService.vendorName$,
      this.instantGamesDataService.rawVendorGames$,
      this.favoriteManagerService.favorites$,
      this.instantGamesDataService.rawCustomersInPlay$,
      this.instantGamesDataService.rawRecentlyPlayed$
    ]) as Observable<
      [
        InstantGameCategory | null,
        string,
        string | null,
        InstantGame[],
        InstantGame[],
        { [key: number]: number },
        InstantGame[]
      ]
    >
  ).pipe(
    map(([category, categoryId, vendorName, vendorGames, favorites, customers, recentlyPlayed]) => {
      if (!category && !vendorName) {
        return null;
      }
      if (vendorName) {
        return this.mapVendorCategory(category, vendorGames, favorites, customers);
      }
      if (category?.type === InstantGameCategoryType.Providers) {
        return { ...category, vendors: this.getVendors(category) };
      }
      return this.mapStandardCategory(category, categoryId, favorites, customers, recentlyPlayed);
    }),
    shareReplay(1)
  );

  private mapStandardCategory(
    category: InstantGameCategory | null,
    categoryId: string | null,
    favorites: InstantGame[],
    customers: Record<number, number>,
    recentlyPlayed: InstantGame[]
  ): InstantGameCategory | null {
    if (!category || !categoryId) return null;

    const favoritesSet: Set<number> = new Set(favorites.map(fav => fav.id));
    const isMobile: boolean = this.mediaService?.media < Media.md;

    // Favorites
    if (category.type === InstantGameCategoryType.Favorites) {
      const mapped: InstantGame[] = favorites.map(game =>
        this.instantGamesDataService.mapGame(game, favoritesSet, customers)
      );
      return {
        ...category,
        instantGames: mapped,
        instantGamesNumber: mapped.length,
        miniMode: false,
        withCounter: mapped.every(game => (game.customersInPlay ?? 0) > 0)
      };
    }

    // RecentlyPlayed
    if (category.type === InstantGameCategoryType.RecentlyPlayed) {
      const mapped: InstantGame[] = recentlyPlayed.map(game =>
        this.instantGamesDataService.mapGame(game, favoritesSet, customers)
      );
      return {
        ...category,
        instantGames: mapped,
        instantGamesNumber: mapped.length,
        miniMode: false,
        withCounter: mapped.every(game => (game.customersInPlay ?? 0) > 0)
      };
    }

    // Standard
    const mappedGames: InstantGame[] = (category.instantGames ?? []).map(game =>
      this.instantGamesDataService.mapGame(game, favoritesSet, customers)
    );

    const miniMode: boolean = category.smallThumbnails && isMobile && this.standardCategories.includes(category.type);

    return {
      ...category,
      instantGames: mappedGames,
      instantGamesNumber: mappedGames.length,
      miniMode,
      withCounter: this.computeWithCounter(mappedGames)
    };
  }

  private mapVendorCategory(
    category: InstantGameCategory | null,
    vendorGames: InstantGame[],
    favorites: InstantGame[],
    customers: Record<number, number>
  ): InstantGameCategory | null {
    if (!category) return null;

    const favoritesSet: Set<number> = new Set(favorites.map(fav => fav.id));

    return {
      ...category,
      vendors: this.getVendors(category),
      instantGames: vendorGames.map(game => this.instantGamesDataService.mapGame(game, favoritesSet, customers)),
      instantGamesNumber: vendorGames.length
    };
  }

  private computeWithCounter(games: InstantGame[]): boolean {
    return games.every(game => (game.customersInPlay ?? 0) > 0);
  }

  private getVendors(category: InstantGameCategory): Vendor[] {
    if (!category?.data) return [];

    return category.data.map((vendor: { name: string; gameCount: number }) => ({
      name: vendor.name,
      gameCount: vendor.gameCount,
      imageUrl: this.getVendorImageUrl(vendor.name)
    }));
  }
}
