import { DOCUMENT, isPlatformBrowser, Location } from '@angular/common';
import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  ElementRef,
  Inject,
  OnDestroy,
  OnInit,
  Optional,
  PLATFORM_ID,
  ViewChild
} from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { Subscription } from 'rxjs';
import { takeUntil } from 'rxjs/operators';
import {
  ApplicationStateService,
  BetCategoryConfigurationService,
  BroadcastingService,
  LocalStorageService
} from '@honoregaming/core';
import {
  AuthService,
  CustomerOperatorConfiguration,
  customerOperatorConfigurationToken,
  FavoritesService,
  FreeBetService,
  IdleService
} from '@honoregaming/customer-core';
import { InstantGameService } from '@honoregaming/events';
import { I18nService } from '@honoregaming/i18n';
import { BetCategoryType, InstantGame, InstantGameMode } from '@honoregaming/types';
import { MediaService, MessageService } from '@honoregaming/ui';
import { InstantGamesConfiguration } from 'projects/core/hg-configuration/src/lib/models';
import { NavBarService } from 'projects/customer/customer/src/app/services';
import { FavoriteManagerService } from 'projects/customer/hg-core/src/lib/services/domain/favorite-manager.service';
import { InstantGamesInGameTournamentBannerComponent } from '../../component/tournaments/instant-games-in-game-tournament-banner/instant-games-in-game-tournament-banner.component';
import { InsaGamesService } from '../../services/insagames.service';
import { InstantGamesFiltersService } from '../../services/instant-games-filters.service';
import { InstantGamesRouteService } from '../../services/instant-games-route.service';
import { InstantGamesHomeComponent } from '../instant-games-home/instant-games-home.component';

@Component({
  selector: 'hg-insa-games',
  templateUrl: './insa-games.component.html',
  styleUrls: ['./insa-games.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class InsaGamesComponent extends InstantGamesHomeComponent implements OnInit, OnDestroy {
  @ViewChild('insaElement') set setInsaElement(element: ElementRef) {
    if (element) {
      this.insaElement = element;
      element.nativeElement.contentWindow.location.replace(this.iframeURL);
    }
  }

  insaElement?: ElementRef;

  @ViewChild('tournamentBanner', { static: true }) tournamentBanner?: InstantGamesInGameTournamentBannerComponent;

  gameRef?: string;
  authToken?: string;
  authTokenTimeout?: NodeJS.Timeout;
  clientId? = this.customerOperatorConfiguration.instantGamesConfiguration.insaGamesClientId;
  mode? = InstantGameMode.Demo;
  customerId?: number;
  language?: string;
  isReady: boolean = false;
  isConnected: boolean = false;
  game?: InstantGame;
  InstantGameMode = InstantGameMode;
  timeOutTokenDate?: number;
  instantGamesBetCategoryPath: string = this.betCategoryConfigurationService.getInstantGamesBetCategoryPath();
  iframeURL?: string;
  classWidget?: string;
  hasTournamentBanner: boolean = false;
  readonly BANNER_HEIGHT: number = 34;
  private getCustomerSubscription?: Subscription;

  private bindingListeners: (event: MessageEvent<any>) => void;

  constructor(
    public readonly authService: AuthService,
    private readonly route: ActivatedRoute,
    public readonly cdRef: ChangeDetectorRef,
    public readonly insaGamesService: InsaGamesService,
    public readonly instantGameService: InstantGameService,
    public readonly router: Router,
    public readonly navBarService: NavBarService,
    public readonly i18nService: I18nService,
    private readonly applicationStateService: ApplicationStateService,
    private readonly storageService: LocalStorageService,
    public readonly location: Location,
    public readonly betCategoryConfigurationService: BetCategoryConfigurationService,
    public readonly favoritesService: FavoritesService,
    public readonly messageService: MessageService,
    private readonly broadcastingService: BroadcastingService,
    public readonly favoriteManagerService: FavoriteManagerService,
    private readonly freeBetService: FreeBetService,
    public readonly instantGamesFiltersService: InstantGamesFiltersService,
    public readonly instantGamesRouteService: InstantGamesRouteService,
    @Inject(DOCUMENT) public document,
    @Inject(customerOperatorConfigurationToken)
    public readonly customerOperatorConfiguration: CustomerOperatorConfiguration,
    @Inject(PLATFORM_ID) public platformId,
    @Optional() public readonly mediaService: MediaService,
    @Optional() private readonly idleService: IdleService
  ) {
    super(
      instantGameService,
      i18nService,
      cdRef,
      route,
      router,
      location,
      betCategoryConfigurationService,
      favoritesService,
      navBarService,
      messageService,
      favoriteManagerService,
      instantGamesFiltersService,
      instantGamesRouteService,
      authService,
      customerOperatorConfiguration,
      document,
      platformId,
      mediaService
    );

    this.bindingListeners = ev => {
      const handlers: { [key: string]: (data: any) => void } = {
        transactionCreated: this.onTransactionCreated.bind(this),
        gameChange: this.onGameChange.bind(this)
      };

      const handler: (data: unknown) => void = handlers[ev.data?.event];
      if (handler) {
        handler(ev.data.data);
      }
    };
  }

  ngOnInit(): void {
    super.ngOnInit();

    this.route.params.pipe(takeUntil(this.destroy$)).subscribe(params => {
      this.gameRef = params['gameRef'];
      this.classWidget = this.gameRef;
      this.generateIframeURL(this.authToken);
      this.loadGame();
    });

    this.cdRef.markForCheck();
    this.broadcastingService.broadcast('display-require-fullscreen', true);

    this.i18nService.languageChanged$.pipe(takeUntil(this.destroy$)).subscribe(language => {
      this.language = language;
      this.generateIframeURL(this.authToken);
      this.cdRef.markForCheck();
    });

    if (isPlatformBrowser(this.platformId)) {
      this.applicationStateService.isReady$.pipe(takeUntil(this.destroy$)).subscribe(() => {
        this.mode = this.storageService.getItem(this.gameRef) || InstantGameMode.Demo;
        this.isReady = true;
        this.cdRef.markForCheck();
        this.getCustomer();
        this.idleService?.stopWatching();
      });
      this.document.defaultView.onfocus = _ => {
        if (this.timeOutTokenDate < Date.now()) {
          this.refreshAuthToken();
        }
      };
    }

    this.tournamentBanner?.activeTournament$.pipe(takeUntil(this.destroy$)).subscribe(tournament => {
      this.hasTournamentBanner = !!tournament;
      this.cdRef.markForCheck();
    });

    this.listenEventIframe();
    this.idleService?.stopWatching();
  }

  ngOnDestroy(): void {
    if (!!this.authTokenTimeout) {
      clearTimeout(this.authTokenTimeout);
    }

    window.removeEventListener('message', this.bindingListeners, false);
    this.navBarService.setNavBarActive(true);
    this.idleService?.startWatching(10 * 6e4);
    this.broadcastingService.broadcast('display-require-fullscreen', false);
    this.getCustomerSubscription?.unsubscribe();
  }

  goToRealMode(): void {
    this.mode = InstantGameMode.Real;
    this.storageService.setItem(this.gameRef, InstantGameMode.Real);
    this.generateIframeURL(this.authToken);
    this.cdRef.markForCheck();
  }

  private refreshAuthToken(): void {
    this.insaGamesService
      .generateAuthToken()
      .pipe(takeUntil(this.destroy$))
      .subscribe(authToken => {
        if (!this.authToken) {
          this.generateIframeURL(authToken.token);
        }
        this.authToken = authToken.token;
        this.sendAuthTokenIframe(this.authToken);
        this.cdRef.markForCheck();
        const expiresInXMSeconds: number = (authToken.expiresIn - 120) * 1000;
        this.timeOutTokenDate = Date.now() + expiresInXMSeconds;
        this.authTokenTimeout = setTimeout(() => this.refreshAuthToken(), expiresInXMSeconds);
      });
  }

  private onTransactionCreated(evt: {
    stake: number;
    balance: number;
    modeType: 'Demo' | 'Real';
    promotions: { isFreeSpin: boolean; freeSpinId: number };
  }): void {
    if (evt.modeType && evt.modeType === 'Demo' && this.mode === InstantGameMode.Real) {
      this.mode = InstantGameMode.Demo;
    }

    if (this.mode === InstantGameMode.Real && evt.promotions?.isFreeSpin) {
      this.freeBetService
        .forceRefreshFreeBetCoupon(false, BetCategoryType.InstantGame)
        .pipe(takeUntil(this.destroy$))
        .subscribe();
    }
  }

  private onGameChange(evt: { oldGame: string; newGame: string }): void {
    this.classWidget = evt.newGame;
    this.cdRef.markForCheck();
  }

  private listenEventIframe(): void {
    window.addEventListener('message', this.bindingListeners, false);
  }

  private getCustomer(): void {
    this.getCustomerSubscription?.unsubscribe();
    this.getCustomerSubscription = this.authService.me$.pipe(takeUntil(this.destroy$)).subscribe(me => {
      this.isConnected = !!me;
      this.customerId = me?.id;
      if (!!this.customerId && !this.authToken) {
        this.refreshAuthToken();
      } else if (!this.customerId) {
        clearTimeout(this.authTokenTimeout);
        this.authToken = null;
        this.sendAuthTokenIframe(this.authToken);
      }

      this.cdRef.markForCheck();
    });
  }

  private loadGame(): void {
    this.instantGameService
      .getInstantGame('InsaGames', this.gameRef)
      .pipe(takeUntil(this.destroy$))
      .subscribe(
        (instantGame: InstantGame | null) => {
          if (instantGame) {
            this.game = instantGame;
            this.navBarService.setNavBarActive(instantGame.navBar);
            this.cdRef.markForCheck();
          }
        },
        () => {
          this.router.navigate([`/${this.instantGamesBetCategoryPath}`]);
        }
      );
  }

  private generateIframeURL(authToken?: string): void {
    const config: InstantGamesConfiguration = this.customerOperatorConfiguration.instantGamesConfiguration;
    if (!config?.insaGamesPath) return;

    // Determine mode
    this.mode = !this.isConnected
      ? InstantGameMode.Demo
      : this.storageService.getItem(this.gameRef) || InstantGameMode.Demo;

    // Fetch customer if needed for Real mode
    if (this.mode === InstantGameMode.Real && this.isConnected && !this.customerId) {
      this.getCustomer();
      return;
    }
    this.iframeURL = `${config.insaGamesPath}iframe/index.html?gameRef=${this.gameRef}&authToken=${encodeURIComponent(
      authToken
    )}&clientId=${this.clientId}&userRef=${this.customerId}&mode=${
      this.mode === InstantGameMode.Real ? 'Real' : 'Demo'
    }&language=${this.language}&displayBalance=${this.mode === InstantGameMode.Real}`;

    if (this.insaElement) {
      // Keep history state clean
      this.insaElement.nativeElement.contentWindow.location.replace(this.iframeURL);
    }

    this.cdRef.detectChanges();
  }

  private sendAuthTokenIframe(authToken: string): void {
    if (this.insaElement?.nativeElement.contentWindow) {
      this.insaElement.nativeElement.contentWindow.postMessage(
        {
          type: 'UPDATE_AUTH_TOKEN_INSA',
          authToken: authToken
        },
        '*'
      );
    }
  }
}
