import { Component, ChangeDetectionStrategy, Inject } from '@angular/core';
import { Observable } from 'rxjs';
import {
  InstantGameBigWinner,
  InstantGameCategory,
  InstantGameCategoryType,
  InstantGameWinnersStream,
  Vendor
} from '@honoregaming/types';
import { AuthService, authServiceToken } from '@honoregaming/authentication';
import { InstantGamesDataService } from '../../services/instant-games-data.service';
import { InstantGamesCategoriesService } from '../../services/instant-games-categories.service';

@Component({
  selector: 'hg-instant-game-categories',
  templateUrl: './instant-game-categories.component.html',
  styleUrls: ['./instant-game-categories.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class InstantGameCategoriesComponent {
  isLoading$: Observable<boolean> = this.categoriesService.isLoading$;
  categories$: Observable<InstantGameCategory[]> = this.categoriesService.mappedCategories$;
  bigWinners$: Observable<InstantGameBigWinner[]> = this.instantGamesDataService.rawBigWinners$;
  winnersStream$: Observable<InstantGameWinnersStream[]> = this.instantGamesDataService.rawWinnersStream$;
  InstantGameCategoryType = InstantGameCategoryType;
  isUserConnected: boolean = this.authService.isAuthenticated();

  constructor(
    protected readonly instantGamesDataService: InstantGamesDataService,
    private readonly categoriesService: InstantGamesCategoriesService,
    @Inject(authServiceToken) public readonly authService: AuthService
  ) {}

  trackBy(_index: number, item: { id: number } | Vendor | InstantGameBigWinner): number | string {
    if ('id' in item) {
      return item.id;
    } else if ('name' in item) {
      return item.name;
    }
    return item.customer;
  }
}
