import {
  Component,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  OnInit,
  Inject,
  PLATFORM_ID,
  Optional
} from '@angular/core';
import { DOCUMENT, Location } from '@angular/common';
import { ActivatedRoute, Router } from '@angular/router';
import { takeUntil } from 'rxjs/operators';
import { Observable } from 'rxjs';
import { InstantGameService } from '@honoregaming/events';
import { I18nService } from '@honoregaming/i18n';
import {
  AuthService,
  CustomerOperatorConfiguration,
  FavoritesService,
  HomePageCustomization,
  customerOperatorConfigurationToken
} from '@honoregaming/customer-core';
import { authServiceToken } from '@honoregaming/authentication';
import { Media, MediaService, MessageService } from '@honoregaming/ui';
import { InstantGame, InstantGameCategoryType, Vendor } from '@honoregaming/types';
import { BetCategoryAutoPaymentConfiguration, globalConfiguration } from '@honoregaming/configuration';
import { BetCategoryConfigurationService, DestroySubject } from '@honoregaming/core';
import { NavBarService } from 'projects/customer/customer/src/app/services';
import { FavoriteManagerService } from 'projects/customer/hg-core/src/lib/services/domain/favorite-manager.service';
import { InstantGamesFiltersService } from '../../services/instant-games-filters.service';
import { InstantGamesRouteService } from '../../services/instant-games-route.service';

@Component({
  selector: 'hg-instant-games-home',
  templateUrl: './instant-games-home.component.html',
  styleUrls: ['./instant-games-home.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class InstantGamesHomeComponent extends DestroySubject implements OnInit {
  isHomePage: boolean = false;
  isUserConnected: boolean = this.authService.isAuthenticated();
  private currentLanguageCode: string = this.i18nService.currentLanguageCode;
  searchText?: string;
  baseAssetsPath: string = this.customerOperatorConfiguration.instantGamesConfiguration.insaGamesAssetsPath;
  assetspath?: string;
  displayBetCategoryNameOnMobile: boolean =
    this.customerOperatorConfiguration.onlineConfiguration?.showBetCategoryNameOnMobile;
  searchGame: boolean = false;
  elementsOrder?: string[];

  filteredGames$: Observable<InstantGame[]> = this.instantGamesFiltersService.filteredGames$;
  filteredVendors$: Observable<Vendor[]> = this.instantGamesFiltersService.filteredVendors$;
  isOnAll$: Observable<boolean> = this.instantGamesRouteService.isOnAll$;
  instantGamesBetCategoryPath: string = this.betCategoryConfigurationService.getInstantGamesBetCategoryPath();

  constructor(
    public readonly instantGameService: InstantGameService,
    public readonly i18nService: I18nService,
    public readonly cdRef: ChangeDetectorRef,
    public readonly activatedRoute: ActivatedRoute,
    public readonly router: Router,
    public readonly location: Location,
    public readonly betCategoryConfigurationService: BetCategoryConfigurationService,
    public readonly favoritesService: FavoritesService,
    public readonly navBarService: NavBarService,
    public readonly messageService: MessageService,
    public readonly favoriteManagerService: FavoriteManagerService,
    public readonly instantGamesFiltersService: InstantGamesFiltersService,
    public readonly instantGamesRouteService: InstantGamesRouteService,
    @Inject(authServiceToken) public readonly authService: AuthService,
    @Inject(customerOperatorConfigurationToken)
    public readonly customerOperatorConfiguration: CustomerOperatorConfiguration,
    @Inject(DOCUMENT) public document,
    @Inject(PLATFORM_ID) public platformId,
    @Optional() public readonly mediaService: MediaService
  ) {
    super();
  }

  public ngOnInit(): void {
    this.isHomePage = this.customerOperatorConfiguration.onlineConfiguration?.homePageCasino;
    const regex: RegExp = new RegExp(/^(https?:\/\/[^/]+)/); // Permet de matcher l'url de base
    const matches: RegExpExecArray = regex.exec(globalConfiguration.assetsPath);
    this.assetspath = matches ? matches[0] : '';

    this.navBarService.setNavBarActive(true);

    this.authService.status$.pipe(takeUntil(this.destroy$)).subscribe(status => {
      const isConnected: boolean = status === 'connected';
      if (this.isUserConnected !== isConnected) {
        this.isUserConnected = isConnected;
      }
    });

    this.i18nService.languageChanged$.pipe(takeUntil(this.destroy$)).subscribe(language => {
      if (this.currentLanguageCode !== language) {
        this.currentLanguageCode = language;
      }
    });

    const homePageCustomization: HomePageCustomization | undefined =
      this.customerOperatorConfiguration.customization['homepage'] ??
      this.customerOperatorConfiguration.customization['sports-homepage'];
    if (homePageCustomization?.elementsOrder) {
      this.elementsOrder =
        homePageCustomization.elementsOrder[this.mediaService?.media >= Media.lg ? 'desktop' : 'mobile'];
    }
  }

  filterGames(): void {
    if (this.searchText && this.searchText.trim().length > 0) {
      this.searchGame = true;
      const searchText: string = this.searchText.toLocaleLowerCase();
      this.instantGamesFiltersService.searchInstantGamesAndVendors(searchText).subscribe();
    } else {
      this.searchGame = false;
      this.instantGamesFiltersService.resetFilters();
      this.cdRef.markForCheck();
    }
  }

  protected canBePaid(paidAmount: number): boolean {
    const autoPaymentConfiguration: BetCategoryAutoPaymentConfiguration | undefined =
      this.customerOperatorConfiguration.autoPaymentLimiterConfiguration?.instantGames;
    return (
      (!autoPaymentConfiguration?.lowerLimit || paidAmount < autoPaymentConfiguration.lowerLimit) &&
      (!autoPaymentConfiguration?.upperLimit || paidAmount < autoPaymentConfiguration.upperLimit)
    );
  }

  onFavoriteToggled({ game, event, categoryType = InstantGameCategoryType.Favorites }): void {
    event.stopPropagation();
    event.preventDefault();
    const isFavoriteCategory: boolean = categoryType === InstantGameCategoryType.Favorites;

    this.favoriteManagerService
      .toggle(game, {
        undoContext: isFavoriteCategory,
        undoAction: () => this.onFavoriteToggled({ game, event: new Event('click'), categoryType })
      })
      .subscribe();
  }
}
