import { Component, ChangeDetectionStrategy, Input, ChangeDetectorRef } from '@angular/core';
import { Router } from '@angular/router';
import { BetCategoryConfigurationService } from '@honoregaming/core';
import { InstantGame, InstantGameCategory } from '@honoregaming/types';
import { FavoriteManagerService } from 'projects/customer/hg-core/src/lib/services/domain/favorite-manager.service';
import { InstantGamesDataService } from '../../../services/instant-games-data.service';
import { CasinoTrackingService } from '../../../services/casino-tracking.service';
import { InstantGameCategoryComponentBase } from '../instant-game-category.component.base';
import { TelemetryService } from '@honoregaming/customer-core';
@Component({
  selector: 'hg-instant-game-animated-category',
  templateUrl: './instant-game-animated-category.component.html',
  styleUrls: ['./instant-game-animated-category.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class InstantGameAnimatedCategoryComponent extends InstantGameCategoryComponentBase {
  @Input() category?: InstantGameCategory;

  constructor(
    public readonly betCategoryConfigurationService: BetCategoryConfigurationService,
    public readonly cdRef: ChangeDetectorRef,
    protected readonly instantGamesDataService: InstantGamesDataService,
    public readonly favoriteManagerService: FavoriteManagerService,
    public readonly router: Router,
    public readonly telemetryService: TelemetryService,
    public readonly casinoTrackingService: CasinoTrackingService
  ) {
    super(
      betCategoryConfigurationService,
      cdRef,
      instantGamesDataService,
      favoriteManagerService,
      router,
      telemetryService,
      casinoTrackingService
    );
  }

  trackBy(_index: number, instantGame: InstantGame): number {
    return instantGame.id;
  }
}
