import { CountdownUnit } from '../types/tournament-detail.types';

export function computeCountdown(endDate: string): CountdownUnit[] {
  const remaining: number = new Date(endDate).getTime() - Date.now();

  if (remaining <= 0) {
    return [
      { value: '00', label: 'GENERIC.DAYS' },
      { value: '00', label: 'GENERIC.HOURS' },
      { value: '00', label: 'GENERIC.MIN' },
      { value: '00', label: 'GENERIC.SEC' }
    ];
  }

  const days: number = Math.floor(remaining / 86400000);
  const hours: number = Math.floor((remaining % 86400000) / 3600000);
  const minutes: number = Math.floor((remaining % 3600000) / 60000);
  const seconds: number = Math.floor((remaining % 60000) / 1000);

  return [
    { value: String(days).padStart(2, '0'), label: 'GENERIC.DAYS' },
    { value: String(hours).padStart(2, '0'), label: 'GENERIC.HOURS' },
    { value: String(minutes).padStart(2, '0'), label: 'GENERIC.MIN' },
    { value: String(seconds).padStart(2, '0'), label: 'GENERIC.SEC' }
  ];
}
