import { Directive, ElementRef, OnInit, OnDestroy, NgZone, Input } from '@angular/core';
import { Router } from '@angular/router';
import { BetCategoryConfigurationService } from '@honoregaming/core';

@Directive({
  selector: 'iframe[hgIframeRedirectionObserver]'
})
export class IframeRedirectionObserverDirective implements OnInit, OnDestroy {
  @Input() hgIframeRedirectionArmed?: boolean;

  private loadListener: () => void;
  private instantGamesBetCategoryPath: string = this.betCategoryConfigurationService.getInstantGamesBetCategoryPath();
  private isAfterInit: boolean = false;

  constructor(
    public readonly betCategoryConfigurationService: BetCategoryConfigurationService,
    private readonly el: ElementRef<HTMLIFrameElement>,
    private readonly router: Router,
    private readonly ngZone: NgZone
  ) {}

  ngOnInit(): void {
    const iframe: HTMLIFrameElement = this.el.nativeElement;

    this.loadListener = () => {
      // --- activation gate ---
      if (this.hgIframeRedirectionArmed !== undefined) {
        // Host drives activation (gameLoaded). Ignore every load until armed.
        if (!this.hgIframeRedirectionArmed) {
          return;
        }
      } else {
        // Generic iframe: original first-load skip.
        if (!this.isAfterInit) {
          this.isAfterInit = true;
          return;
        }
      }

      try {
        const href: string = iframe.contentWindow?.location.href;

        if (!href || href === 'about:blank' || href === iframe.src) {
          return;
        }

        const url: URL = new URL(href);

        if (url.origin === window.location.origin) {
          this.ngZone.run(() => {
            this.router.navigateByUrl(url.pathname + url.search + url.hash);
          });
        } else {
        }
      } catch (err) {
        console.warn('cross-origin detected, cannot read href');

        this.ngZone.run(() => {
          this.router.navigate([`/${this.instantGamesBetCategoryPath}`]);
        });
      }
    };

    this.ngZone.runOutsideAngular(() => {
      iframe.addEventListener('load', this.loadListener);
    });
  }

  ngOnDestroy(): void {
    this.el.nativeElement.removeEventListener('load', this.loadListener);
  }
}
