import { Observable, Subject } from 'rxjs';
import { Injectable } from '@angular/core';
import { RouletteGameHistory, RouletteItemColor } from '@honoregaming/types';

@Injectable({ providedIn: 'root' })
export class RouletteService {
  private rouletteHistorySubject: Subject<RouletteGameHistory>;
  private rouletteGameHistory: RouletteGameHistory;
  $rouletteHistory: Observable<RouletteGameHistory>;

  constructor() {
    this.rouletteHistorySubject = new Subject();
    this.$rouletteHistory = this.rouletteHistorySubject.asObservable();
  }

  addRouletteHistoryElement(paidAmount: number, result: number, color: RouletteItemColor) {
    this.rouletteGameHistory = {
      paidAmount,
      result,
      color
    };
    this.rouletteHistorySubject.next(this.rouletteGameHistory);
  }
}
