import {
  OnInit,
  Component,
  ChangeDetectorRef,
  ViewChild,
  ElementRef,
  Inject,
  HostListener,
  PLATFORM_ID,
  OnDestroy
} from '@angular/core';
import { InstantGameMode, InstantGameState, InstantGameName, InstantGame } from '@honoregaming/types';
import { AuthService } from '@honoregaming/customer-core';
import { LocalStorageService, DestroySubject, BetCategoryConfigurationService } from '@honoregaming/core';
import { BettingApiService, BettingError, CreateBetFailures } from '@honoregaming/betslip';
import { DOCUMENT, isPlatformBrowser } from '@angular/common';
import { Router, NavigationEnd } from '@angular/router';
import { finalize, takeUntil } from 'rxjs/operators';
import { GenericContentComponent, MessageService } from '@honoregaming/ui';
import { BalanceNotEnoughComponent } from '@honoregaming/customer-ui';
import { InstantGameService } from '@honoregaming/events';
import { I18nService } from '@honoregaming/i18n';
import { NavBarService } from 'projects/customer/customer/src/app/services';
import { CreateInstantGameTransactionFailure } from 'projects/core/hg-betslip/src/lib/models/create-instantgame-transaction-failre.enum';

const penaltyMode = 'penalty-mode';
const maxGainMultiplier = 2000;

@Component({
  selector: 'hg-penalty-game',
  templateUrl: './penalty-game.component.html',
  styleUrls: ['./penalty-game.component.scss']
})
export class PenaltyGameComponent extends DestroySubject implements OnInit, OnDestroy {
  gameInProgress = false;
  gameMode = InstantGameMode;
  loading: boolean;
  mode: InstantGameMode;
  stake: number;
  toggleRules = false;
  displayAmount = false;
  isAllscratched = false;
  gain: number;
  result: InstantGameState;
  amount: number;
  loggedIn: boolean;
  languageCur: string;
  balance: number;
  canvasReady = false;
  balls: { gain: number; isDisplay: boolean }[] = [];
  canvasBalls: { reference: ElementRef }[] = [];
  ballDisplayCounter = 0;
  paidAmount: number;
  maxAmount: number;
  lockTransaction = false;
  displayValues = false;
  countWinNumberScratched = 0;
  numberbBalls = 5;
  img: HTMLImageElement;
  scratchAudio: HTMLAudioElement;
  whistleAudio: HTMLAudioElement;
  isDrawing = false;
  gainImg: HTMLImageElement;
  @ViewChild('ball1') ballElementRef_1: ElementRef;
  @ViewChild('ball2') ballElementRef_2: ElementRef;
  @ViewChild('ball3') ballElementRef_3: ElementRef;
  @ViewChild('ball4') ballElementRef_4: ElementRef;
  @ViewChild('ball5') ballElementRef_5: ElementRef;
  @ViewChild('gainButton') gainElementRef: ElementRef;

  instantGamesBetCategoryPath = this.betCategoryConfigurationService.getInstantGamesBetCategoryPath();

  constructor(
    private instantGameService: InstantGameService,
    private bettingApiService: BettingApiService,
    private cdRef: ChangeDetectorRef,
    @Inject(PLATFORM_ID) private platformId,
    private authService: AuthService,
    private router: Router,
    private storageService: LocalStorageService,
    @Inject(DOCUMENT) private document,
    private messageService: MessageService,
    private i18nService: I18nService,
    private navBarService: NavBarService,
    private betCategoryConfigurationService: BetCategoryConfigurationService
  ) {
    super();
  }

  ngOnInit() {
    if (isPlatformBrowser(this.platformId)) {
      this.scratchAudio = new Audio('/assets/instant-games/penalty/sounds/scratch.mp3');
      this.whistleAudio = new Audio('/assets/instant-games/penalty/sounds/whistle.mp3');
      this.img = new Image(80, 80);
      this.img.src = '/assets/instant-games/penalty/ball.svg';
      this.gainImg = new Image(160, 60);
      this.i18nService.languageChanged$.pipe(takeUntil(this.destroy$)).subscribe(language => {
        this.languageCur = language;
        this.gainImg.src = '/assets/instant-games/penalty/gain.svg';
        this.gainImg.onload = () => {
          if (this.gainElementRef) {
            this.drawElement(
              this.gainElementRef.nativeElement,
              this.gainElementRef.nativeElement.getContext('2d'),
              'gain'
            );
          }
          this.cdRef.markForCheck();
        };
      });
    }

    this.instantGameService
      .getInstantGames()
      .pipe(takeUntil(this.destroy$))
      .subscribe((gamesList: InstantGame[]) => {
        const penalty = gamesList
          .filter(g => g.provider.toLowerCase() === 'internal')
          .find(g => g.name === InstantGameName.Penalty);

        if (penalty) {
          this.navBarService.setNavBarActive(penalty.navBar);
        } else {
          this.router.navigate([`/${this.instantGamesBetCategoryPath}`]);
        }

        const configuration = penalty?.configuration;
        this.authService.me$.pipe(takeUntil(this.destroy$)).subscribe(me => {
          if (me) {
            this.loggedIn = true;
            this.balance = me.balance;
          } else {
            this.loggedIn = false;
          }
          this.cdRef.markForCheck();
        });
        this.mode = this.storageService.getItem(penaltyMode) || InstantGameMode.Demo;

        if (configuration) {
          this.stake = configuration.baseAmount;
          this.maxAmount = configuration.baseAmount * maxGainMultiplier;
          this.cdRef.markForCheck();
        }
      });

    this.router.events.subscribe(event => {
      if (event instanceof NavigationEnd) {
        this.musicStop();
      }
    });
  }

  @HostListener('touchend')
  @HostListener('mouseup')
  onDrawingEnd() {
    this.isDrawing = false;
  }

  ngOnDestroy() {
    super.ngOnDestroy();
    this.navBarService.setNavBarActive(true);
  }

  start() {
    if (!this.gameInProgress && !this.lockTransaction) {
      if (this.balance < this.stake && (this.loggedIn ? this.mode : InstantGameMode.Demo) !== InstantGameMode.Demo) {
        this.messageService.sendComponentMessage(BalanceNotEnoughComponent, {
          titleTranslation: 'POPIN.BALANCE_NOT_ENOUGH_FOR_TRANSACTION.TITLE',
          bodyTranslation: 'POPIN.BALANCE_NOT_ENOUGH_FOR_TRANSACTION'
        });
        return;
      }

      this.loading = true;
      this.lockTransaction = true;
      const betslip: { [index: number]: number } = {};
      betslip[0] = this.stake;
      this.gameInProgress = true;
      this.bettingApiService
        .createInstantGameTransaction({
          instantGameMode: this.loggedIn ? this.mode : InstantGameMode.Demo,
          instantGameName: InstantGameName.Penalty,
          stake: this.stake,
          selection: betslip
        })
        .pipe(
          takeUntil(this.destroy$),
          finalize(() => {
            this.loading = false;
            this.cdRef.markForCheck();
          })
        )
        .subscribe(
          response => {
            const resp = response.result['selectionResult'];
            this.gain = resp[this.numberbBalls];
            this.addBalls();
            for (let val = 0; val < this.numberbBalls; val++) {
              this.balls[val].gain = resp[val];
            }
            this.result = response.state;
            this.paidAmount = this.result === InstantGameState.Won ? this.gain : 0;
            setTimeout(() => {
              this.handleCanvas();
            });
          },
          (err: BettingError) => {
            switch (err.failure) {
              case CreateBetFailures.TooManyRequests:
                this.messageService
                  .sendComponentMessage(GenericContentComponent, {
                    text: this.i18nService.translateSync('INSTANT-GAMES.ERRORS.TOO_MANY_REQUESTS')
                  })
                  .closed.subscribe(_ => {
                    this.gameInProgress = false;
                    this.lockTransaction = false;
                    this.cdRef.markForCheck();
                  });
                break;
              case CreateInstantGameTransactionFailure.CustomerLimitationExceeded:
              case CreateInstantGameTransactionFailure.CustomerSelfExcluded:
                this.messageService
                  .sendComponentMessage(
                    GenericContentComponent,
                    {
                      title: this.i18nService.translateSync('RESPONSIBLE_GAMBLING.SELF_LIMITATION'),
                      text: this.i18nService.translateSync('BET-SLIP.BETTING_ERROR.LIMIT_REACHED')
                    },
                    { canBeDismissed: true, displayClose: true, dark: true }
                  )
                  .closed.subscribe(_ => {
                    this.gameInProgress = false;
                    this.lockTransaction = false;
                    this.cdRef.markForCheck();
                  });
            }
          }
        );
    }
  }

  displayAmountToWin() {
    this.displayAmount = true;
    this.updateBalance();
  }

  reset() {
    this.gain = undefined;
    this.displayAmount = false;
    this.isAllscratched = false;
    this.gameInProgress = false;
    this.lockTransaction = false;
    this.displayValues = false;
    this.canvasReady = false;
    this.ballDisplayCounter = 0;
    this.countWinNumberScratched = 0;
    this.balls = [];
    this.canvasBalls = [];
    this.cdRef.markForCheck();
  }

  handleCanvas(): void {
    this.drawElement(this.gainElementRef.nativeElement, this.gainElementRef.nativeElement.getContext('2d'), 'gain');
    this.handleScratch(this.gainElementRef.nativeElement, this.gainElementRef.nativeElement.getContext('2d'), null);
    this.addCanvas(this.ballElementRef_1);
    this.addCanvas(this.ballElementRef_2);
    this.addCanvas(this.ballElementRef_3);
    this.addCanvas(this.ballElementRef_4);
    this.addCanvas(this.ballElementRef_5);
    for (let i = 0; i < this.numberbBalls; i++) {
      this.drawElement(
        this.canvasBalls[i].reference.nativeElement,
        this.canvasBalls[i].reference.nativeElement.getContext('2d'),
        'ball'
      );
      setTimeout(() => {
        this.canvasReady = true;
        this.cdRef.markForCheck();
      });

      this.handleScratch(
        this.canvasBalls[i].reference.nativeElement,
        this.canvasBalls[i].reference.nativeElement.getContext('2d'),
        i
      );
    }
  }

  addCanvas(reference: ElementRef) {
    const ball = {
      reference: reference
    };
    this.canvasBalls.push(ball);
  }

  musicStop() {
    this.scratchAudio.pause();
    this.scratchAudio.currentTime = 0;
  }
  scratchPlay() {
    if (this.scratchAudio.duration > 0 && !this.scratchAudio.paused) {
      return;
    } else {
      this.scratchAudio.play();
    }
  }

  addBalls() {
    for (let i = 0; i < this.numberbBalls; i++) {
      const ball = {
        gain: 0,
        isDisplay: false
      };
      this.balls.push(ball);
    }
  }

  drawElement(ref: any, context: CanvasRenderingContext2D, element: string) {
    if (element === 'ball') {
      ref.width = this.img.naturalWidth;
      ref.height = this.img.naturalHeight;
      context.drawImage(this.img, 0, 0, ref.width, ref.height);
    } else {
      ref.width = this.gainImg.naturalWidth;
      ref.height = this.gainImg.naturalHeight;
      context.clearRect(0, 0, ref.width, ref.height);
      context.drawImage(this.gainImg, 0, 0, ref.width, ref.height);
      context.font = 'bold 20px Roboto';
      context.textBaseline = 'middle';
      context.textAlign = 'center';
      context.fillStyle = 'white';
      context.fillText(
        this.i18nService.translateSync('INSTANT-GAMES.GAIN').toUpperCase(),
        ref.width / 2,
        ref.height / 2 + 2
      );
    }
  }

  handleScratch(element: HTMLElement, context: CanvasRenderingContext2D, id: number) {
    element.addEventListener(
      'mousedown',
      () => {
        this.displayValues = true;
        this.isDrawing = true;
        this.cdRef.markForCheck();
        this.mouseDown();
      },
      false
    );

    element.addEventListener(
      'mousemove',
      (e: Event) => {
        if (this.isDrawing) {
          this.mouseMove(e, element, context, id);
        }
      },
      false
    );

    element.addEventListener(
      'mouseup',
      () => {
        this.isDrawing = false;
        (<any>element).startX = null;
        (<any>element).startY = null;
      },
      false
    );

    element.addEventListener(
      'touchstart',
      () => {
        this.displayValues = true;
        this.isDrawing = true;
        this.cdRef.markForCheck();
        this.touchStart();
      },
      false
    );

    element.addEventListener(
      'touchmove',
      (e: Event) => {
        if (this.isDrawing) {
          this.mouseMove(e, element, context, id);
        }
      },
      false
    );

    element.addEventListener(
      'touchend',
      () => {
        this.isDrawing = false;
        (<any>element).startX = null;
        (<any>element).startY = null;
      },
      false
    );
  }

  mouseMove(event: any, element, context: CanvasRenderingContext2D, id: number) {
    if (event.originalEvent !== undefined && event.cancelable) {
      event.preventDefault();
    }
    let x: number;
    let y: number;
    if (event.targetTouches) {
      const rect = event.target.getBoundingClientRect();
      x = event.targetTouches[0].pageX - rect.left;
      y = event.targetTouches[0].pageY - (rect.top + this.document?.scrollingElement?.scrollTop);
    } else {
      x = event.offsetX || event.layerX;
      y = event.offsetY || event.layerY;
    }

    if (element.startX && element.startY) {
      context.globalCompositeOperation = 'destination-out';
      context.lineWidth = 18;
      context.lineJoin = 'round';
      context.beginPath();
      context.moveTo(element.startX, element.startY);
      context.lineTo(x, y);
      context.fill();
      context.closePath();
      context.stroke();
    }
    this.scratchPlay();

    element.startX = x;
    element.startY = y;
    this.handlePercentage(this.getFilledInPixels(32, context), element, id);
  }

  mouseDown() {
    this.scratchPlay();
  }

  touchStart() {
    this.scratchPlay();
  }

  getFilledInPixels(stride: number, context: CanvasRenderingContext2D) {
    if (!stride || stride < 1) {
      stride = 1;
    }

    const pixels = context.getImageData(0, 0, 80, 80),
      pdata = pixels.data,
      l = pdata.length,
      total = l / stride;
    let count = 0;

    for (let i = 0; i < l; i += stride) {
      if (pdata[i] === 0) {
        count++;
      }
    }

    return Math.round((count / total) * 100);
  }

  handlePercentage(filledInPixels: number, element: any, id: number) {
    filledInPixels = filledInPixels || 0;

    if (id != null) {
      if (filledInPixels > 70 && element.parentNode) {
        element.parentNode.removeChild(element);
        this.ballDisplayCounter++;
        this.balls[id].isDisplay = true;
        this.countScratchedWinningBall(id);
        this.updateBalance();
      }
    } else {
      if (filledInPixels > 60 && element.parentNode) {
        this.displayAmountToWin();
        element.parentNode.removeChild(element);
      }
    }
  }

  switchMode() {
    this.storageService.setItem(penaltyMode, InstantGameMode.Real);
    this.mode = InstantGameMode.Real;
    this.cdRef.markForCheck();
  }

  updateBalance() {
    if (
      (this.ballDisplayCounter === this.numberbBalls && this.displayAmount) ||
      (this.countWinNumberScratched === 2 && this.displayAmount)
    ) {
      setTimeout(() => {
        this.isAllscratched = true;
        this.musicStop();
        this.whistleAudio.play();
        this.cdRef.markForCheck();
      }, 1000);
      setTimeout(() => {
        if (this.loggedIn) {
          this.authService
            .getBalance()
            .pipe(takeUntil(this.destroy$))
            .subscribe(x => {
              this.balance = x.balance;
              this.reset();
            });
        } else {
          this.reset();
        }
      }, 3000);
    }
  }

  revealAll() {
    this.displayValues = true;
    for (let i = 0; i < this.numberbBalls; i++) {
      if (this.canvasBalls[i].reference?.nativeElement?.parentNode) {
        this.canvasBalls[i].reference.nativeElement.parentNode.removeChild(this.canvasBalls[i].reference.nativeElement);
        this.ballDisplayCounter++;
        this.balls[i].isDisplay = true;
        this.countScratchedWinningBall(i);
        this.updateBalance();
      }
    }
  }

  countScratchedWinningBall(ballId: number) {
    if (this.paidAmount > 0 && this.balls[ballId].gain === this.paidAmount && this.balls[ballId].isDisplay) {
      this.countWinNumberScratched++;
    }
  }
}
