import { DOCUMENT, isPlatformBrowser } from '@angular/common';
import { Component, ChangeDetectionStrategy, Input, EventEmitter, Output, Inject, PLATFORM_ID } from '@angular/core';
import { Router } from '@angular/router';
import { Observable } from 'rxjs';
import { BetCategoryConfigurationService } from '@honoregaming/core';
import { InstantGame, Vendor } from '@honoregaming/types';
import { InstantGamesDataService } from '../../services/instant-games-data.service';
import { TelemetryService } from '@honoregaming/customer-core';

@Component({
  selector: 'hg-search-games-results',
  templateUrl: './search-games-results.component.html',
  styleUrls: ['./search-games-results.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class SearchGamesResultsComponent {
  @Input() searchText?: string;
  @Input() vendors: Observable<Vendor[]> | null = null;
  @Input() games: Observable<InstantGame[]> | null = null;

  @Output() favoriteToggled = new EventEmitter<{ game: InstantGame; event: Event }>();

  instantGamesBetCategoryPath: string = this.betCategoryConfigurationService.getInstantGamesBetCategoryPath();
  providersCategoryId$: Observable<number> = this.instantGamesDataService.providersCategoryId$;

  constructor(
    public readonly router: Router,
    public readonly telemetryService: TelemetryService,
    private readonly betCategoryConfigurationService: BetCategoryConfigurationService,
    private readonly instantGamesDataService: InstantGamesDataService,
    @Inject(DOCUMENT) public document,
    @Inject(PLATFORM_ID) public platformId
  ) {}

  gameClicked(gameName: string): void {
    if (isPlatformBrowser(this.platformId)) {
      this.document.querySelector('body').scrollTo(0, 0);
    }

    this.telemetryService.trackEvent('casino_game_click', { search_term: this.searchText, game_name: gameName });
  }

  vendorClicked(providerName: string) {
    if (isPlatformBrowser(this.platformId)) {
      this.document.querySelector('body').scrollTo(0, 0);
    }

    this.telemetryService.trackEvent('casino_vendor_click', {
      search_term: this.searchText,
      provider_name: providerName
    });
  }

  toggleFavorite(game: InstantGame, event: Event): void {
    event.stopPropagation();
    event.preventDefault();
    this.favoriteToggled.emit({ game, event });
  }

  trackBy(_index: number, item: { id?: number; name?: string }): number | string {
    return item.id ?? item.name!;
  }
}
