import { DOCUMENT, isPlatformBrowser, Location } from '@angular/common';
import { Component, ChangeDetectionStrategy, PLATFORM_ID, Inject } from '@angular/core';
import { Router } from '@angular/router';
import { map, shareReplay, take } from 'rxjs/operators';
import { combineLatest, Observable } from 'rxjs';
import { AuthService, authServiceToken } from '@honoregaming/authentication';
import { BetCategoryConfigurationService, DestroySubject } from '@honoregaming/core';
import {
  CustomerOperatorConfiguration,
  customerOperatorConfigurationToken,
  FavoritesService,
  TelemetryService
} from '@honoregaming/customer-core';
import { InstantGame, InstantGameCategory, InstantGameCategoryType, Vendor } from '@honoregaming/types';
import { MessageService, SendComponentMessageOptions } from '@honoregaming/ui';
import { ContentComponent } from 'projects/core/hg-templating/src/lib/content/content.component';
import { FavoriteManagerService } from 'projects/customer/hg-core/src/lib/services/domain/favorite-manager.service';
import { InstantGamesCategoriesService } from '../../services/instant-games-categories.service';
import { InstantGamesRouteService } from '../../services/instant-games-route.service';
import { InstantGamesDataService } from '../../services/instant-games-data.service';
import { CasinoTrackingService } from '../../services/casino-tracking.service';

@Component({
  selector: 'hg-instant-games-list',
  templateUrl: './instant-games-list.component.html',
  styleUrls: ['./instant-games-list.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class InstantGamesListComponent extends DestroySubject {
  currentCategoryId$ = this.instantGamesRouteService.activeCategoryId$;
  category$: Observable<InstantGameCategory> = this.categoriesService.categoryViewModel$;

  readonly hotCategory$: Observable<InstantGameCategory> = this.instantGamesDataService.rawCategories$.pipe(
    map(cats => cats.find(category => category.type === 'HotGames') ?? null),
    shareReplay(1)
  );

  readonly coldCategory$: Observable<InstantGameCategory> = this.instantGamesDataService.rawCategories$.pipe(
    map(cats => cats.find(category => category.type === 'ColdGames') ?? null),
    shareReplay(1)
  );

  isVendorCategory$: Observable<boolean> = this.instantGamesRouteService.vendorName$.pipe(map(name => !!name));

  InstantGameCategoryType = InstantGameCategoryType;
  instantGamesBetCategoryPath: string = this.betCategoryConfigurationService.getInstantGamesBetCategoryPath();
  isUserConnected$: Observable<boolean> = this.instantGamesDataService.isUserConnected$;

  vendorName$: Observable<string> = this.instantGamesRouteService.vendorName$;
  vendor$: Observable<{
    name?: string;
    imageUrl?: string;
  }> = this.vendorName$.pipe(
    map(name =>
      name
        ? {
            name,
            imageUrl: this.categoriesService.getVendorImageUrl(name)
          }
        : null
    )
  );

  vendorGames$: Observable<InstantGame[]> = this.instantGamesDataService.rawVendorGames$;

  constructor(
    private readonly router: Router,
    private readonly betCategoryConfigurationService: BetCategoryConfigurationService,
    private readonly messageService: MessageService,
    private readonly instantGamesDataService: InstantGamesDataService,
    public readonly favoritesService: FavoritesService,
    public readonly favoriteManagerService: FavoriteManagerService,
    private readonly instantGamesRouteService: InstantGamesRouteService,
    private readonly categoriesService: InstantGamesCategoriesService,
    private readonly location: Location,
    private readonly casinoTrackingService: CasinoTrackingService,
    @Inject(authServiceToken) public readonly authService: AuthService,
    @Inject(customerOperatorConfigurationToken)
    public readonly customerOperatorConfiguration: CustomerOperatorConfiguration,
    @Inject(DOCUMENT) public document,
    @Inject(PLATFORM_ID) public platformId,
    public readonly telemetryService: TelemetryService
  ) {
    super();
  }

  openRtpInfoPopin(): void {
    this.messageService.sendComponentMessage(ContentComponent, { name: 'rtp-infos' }, {
      maxWidth: 500,
      className: 'content-popin',
      id: 'RTP_Info_Popin',
      canBeDismissed: true,
      displayClose: true
    } as SendComponentMessageOptions);
  }

  goBack(): void {
    this.location.back();
  }

  clickOnBack() {
    const navDepth = parseInt(sessionStorage['navigation_depth']);

    if (navDepth === 0) {
      this.router.navigate(['/']);
    } else if (navDepth <= 1) {
      const currentRouteUrl = sessionStorage['current_route']?.split('?')?.[0] ?? '';
      const currentRouteParams = currentRouteUrl.split('/').filter(i => i);
      let targetPath = currentRouteParams.length > 0 ? currentRouteParams[0] : '';

      this.router.navigate(['/' + targetPath]);
    } else if (navDepth > 1) {
      this.location.back();
    }
  }

  trackByGame(_index: number, game: InstantGame): number {
    return game.id;
  }

  trackByVendor(_index: number, vendor: Vendor): string {
    return vendor.name;
  }

  toggleFavorite(game: InstantGame, event: Event, category: InstantGameCategory): void {
    event.stopPropagation();
    event.preventDefault();
    const isFavoriteCategory: boolean = category?.type === InstantGameCategoryType.Favorites;

    this.favoriteManagerService
      .toggle(game, {
        undoContext: isFavoriteCategory,
        undoAction: () => this.toggleFavorite(game, new Event('click'), category)
      })
      .subscribe();
  }

  toggleRtpCategory(): void {
    combineLatest([this.category$, this.hotCategory$, this.coldCategory$])
      .pipe(take(1))
      .subscribe(([category, hotCategory, coldCategory]) => {
        if (!hotCategory || !coldCategory) return;

        const isHot: boolean = category?.type === 'HotGames';
        const next = isHot ? coldCategory : hotCategory;

        this.router.navigate([`/${this.instantGamesBetCategoryPath}/category`, next.id.toString()]);
        sessionStorage['navigation_depth'] = 0;
      });
  }

  gameClicked(gameName: string, category: InstantGameCategory, position: number): void {
    if (isPlatformBrowser(this.platformId)) {
      this.document.querySelector('body').scrollTo(0, 0);
    }

    this.telemetryService.trackEvent('casino_game_click', { game_name: gameName });
    this.casinoTrackingService.trackCategoryGameSelect(gameName, category, position);
  }

  onVendorClick(categoryId: number, providerName: string): void {
    this.telemetryService.trackEvent('casino_vendor_click', {
      provider_name: providerName
    });
    this.router.navigate([`/${this.instantGamesBetCategoryPath}/category`, categoryId, providerName]);
  }
}
