import {
  Component,
  ChangeDetectionStrategy,
  AfterViewInit,
  ViewChild,
  ElementRef,
  ChangeDetectorRef,
  OnInit,
  Optional,
  OnDestroy
} from '@angular/core';
import { InstantGameService } from '@honoregaming/events';
import { BettingApiService, BettingError, CreateBetFailures } from '@honoregaming/betslip';
import { InstantGame, InstantGameMode, InstantGameName, InstantGameState } from '@honoregaming/types';
import { takeUntil } from 'rxjs/operators';
import { LocalStorageService, DestroySubject, shuffleArray, BetCategoryConfigurationService } from '@honoregaming/core';
import { MusikaPopinComponent } from './musika-popups/musika-popin.component';
import { GenericContentComponent, Media, MediaService, MessageService } from '@honoregaming/ui';
import { reanimate } from '@honoregaming/ui';
import { AuthService } from '@honoregaming/customer-core';
import { BalanceNotEnoughComponent } from '@honoregaming/customer-ui';
import { MusikaStatus } from '../../enums/musika.enum';
import { musikaInstruments } from '../../constants/musika-instruments';
import { BehaviorSubject } from 'rxjs';
import { I18nService } from '@honoregaming/i18n';
import { NavBarService } from 'projects/customer/customer/src/app/services';
import { CreateInstantGameTransactionFailure } from 'projects/core/hg-betslip/src/lib/models/create-instantgame-transaction-failre.enum';
import { Router } from '@angular/router';

const musikaMode = 'musika-mode';
const musikaLocalStorageKey = 'musikaStake';

@Component({
  selector: 'hg-musika',
  templateUrl: './musika.component.html',
  styleUrls: ['./musika.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class MusikaComponent extends DestroySubject implements AfterViewInit, OnInit, OnDestroy {
  instruments: { path: string; id: number }[];
  suffledInstrumentsReelOne: { path: string; id: number }[];
  suffledInstrumentsReelTwo: { path: string; id: number }[];
  suffledInstrumentsReelThree: { path: string; id: number }[];
  result: number[] = [];
  gameResult: string;
  paidAmount: number;
  payableAmount: number;
  stakes: number[];
  currentStake: number;
  gains = [];
  transactionId: number;
  gameMode = InstantGameMode;
  loggedIn: boolean;
  mode: InstantGameMode;
  balance: number;

  lockPlayBtn: boolean;
  userIsPlaying: BehaviorSubject<boolean> = new BehaviorSubject(false);
  showPlayNowBtn: boolean = true;

  instantGameMode = InstantGameMode;

  configuration: any;

  @ViewChild('ring1') ringOneElementRef: ElementRef;
  @ViewChild('ring2') ringTwoElementRef: ElementRef;
  @ViewChild('ring3') ringThreeElementRef: ElementRef;

  readonly slotsPerReel = 12;
  readonly slotAngle = 360 / this.slotsPerReel;
  reelRadius: number;

  instantGamesBetCategoryPath = this.betCategoryConfigurationService.getInstantGamesBetCategoryPath();

  constructor(
    private instantGameService: InstantGameService,
    private bettingApiService: BettingApiService,
    private router: Router,
    private messageService: MessageService,
    private authService: AuthService,
    private cdRef: ChangeDetectorRef,
    private storageService: LocalStorageService,
    private localStorageService: LocalStorageService,
    private i18nService: I18nService,
    @Optional() protected mediaService: MediaService,
    private navBarService: NavBarService,
    private betCategoryConfigurationService: BetCategoryConfigurationService
  ) {
    super();
  }
  ngAfterViewInit(): void {
    this.suffledInstrumentsReelOne = this.createSlots(this.ringOneElementRef);
    this.suffledInstrumentsReelTwo = this.createSlots(this.ringTwoElementRef);
    this.suffledInstrumentsReelThree = this.createSlots(this.ringThreeElementRef);
  }

  ngOnInit(): void {
    this.instruments = musikaInstruments;

    this.authService.me$.pipe(takeUntil(this.destroy$)).subscribe(me => {
      if (me) {
        this.loggedIn = true;
        this.balance = me.balance;
        this.mode = this.storageService.getItem(musikaMode) || InstantGameMode.Demo;
      } else {
        this.loggedIn = false;
        this.mode = InstantGameMode.Demo;
      }
      this.cdRef.markForCheck();
    });

    this.instantGameService
      .getInstantGames()
      .pipe(takeUntil(this.destroy$))
      .subscribe((gamesList: InstantGame[]) => {
        const musika = gamesList
          .filter(g => g.provider.toLowerCase() === 'internal')
          .find(g => g.name === InstantGameName.Musika);

        if (musika) {
          this.navBarService.setNavBarActive(musika.navBar);
        } else {
          this.router.navigate([`/${this.instantGamesBetCategoryPath}`]);
        }

        this.configuration = musika?.configuration;
        if (this.configuration) {
          this.currentStake = this.localStorageService.getItem(musikaLocalStorageKey)
            ? this.localStorageService.getItem(musikaLocalStorageKey)
            : this.configuration.baseAmount;
          this.localStorageService.setItem(musikaLocalStorageKey, this.currentStake);
          this.stakes = this.configuration.stakes;
          this.gains = this.configuration.odds.map(x => x * this.currentStake);
          this.cdRef.markForCheck();
        }
      });
  }

  ngOnDestroy() {
    super.ngOnDestroy();
    this.navBarService.setNavBarActive(true);
  }

  createSlots(ring: ElementRef) {
    const slotArray = shuffleArray([...this.instruments]);
    if (this.mediaService) {
      this.mediaService.media$.subscribe(screenSize => {
        this.reelRadius = screenSize < Media.sm ? 220 : 320;
      });
    }

    for (let i = 0; i < this.slotsPerReel; i++) {
      let slot = document.createElement('div');
      slot.className = 'slot';
      let transform = 'rotateX(' + this.slotAngle * i + 'deg) translateZ(' + this.reelRadius + 'px)';
      slot.style.transform = transform;
      let content = slot.appendChild(document.createElement('img'));
      content.src = slotArray[i % this.instruments.length].path;
      content.className = 'slot-img';
      (<HTMLElement>ring.nativeElement).appendChild(slot);
    }
    return slotArray;
  }

  switchMode() {
    if (this.lockPlayBtn && this.mode === InstantGameMode.Demo) {
      this.showPlayNowBtn = false;
      this.userIsPlaying.pipe(takeUntil(this.destroy$)).subscribe(x => {
        if (!x) {
          this.switchToReal();
        }
      });
    } else {
      this.switchToReal();
    }
  }

  private switchToReal() {
    this.storageService.setItem(musikaMode, InstantGameMode.Real);
    this.mode = InstantGameMode.Real;
    this.cdRef.markForCheck();
  }

  createMusikaInstantGameTransaction() {
    if (
      this.balance < this.currentStake &&
      (this.loggedIn ? this.mode : InstantGameMode.Demo) !== InstantGameMode.Demo
    ) {
      this.messageService.sendComponentMessage(BalanceNotEnoughComponent, {
        titleTranslation: 'POPIN.BALANCE_NOT_ENOUGH_FOR_TRANSACTION.TITLE',
        bodyTranslation: 'POPIN.BALANCE_NOT_ENOUGH_FOR_TRANSACTION'
      });
    } else if (!this.lockPlayBtn) {
      this.lockPlayBtn = true;
      this.userIsPlaying.next(true);
      const selection: { [index: number]: number } = {};
      selection[0] = this.currentStake;
      this.bettingApiService
        .createInstantGameTransaction({
          instantGameMode: this.loggedIn ? this.mode : InstantGameMode.Demo,
          instantGameName: InstantGameName.Musika,
          stake: this.currentStake,
          selection: selection
        })
        .pipe(takeUntil(this.destroy$))
        .subscribe(
          r => {
            this.transactionId = r.id;
            this.result = [r.result.resultColumn1, r.result.resultColumn2, r.result.resultColumn3];
            this.gameResult = r.state;
            this.paidAmount = r.paidAmount;
            this.payableAmount = r.result.payableAmount;

            this.spin({
              timer: 2.5,
              reelRef: this.ringOneElementRef,
              spinId: this.suffledInstrumentsReelOne.findIndex(x => x.id === this.result[0])
            });
            this.spin({
              timer: 3,
              reelRef: this.ringTwoElementRef,
              spinId: this.suffledInstrumentsReelTwo.findIndex(x => x.id === this.result[1])
            });
            this.spin({
              timer: 3.5,
              reelRef: this.ringThreeElementRef,
              spinId: this.suffledInstrumentsReelThree.findIndex(x => x.id === this.result[2])
            });

            setTimeout(() => {
              if (!this.cdRef['destroyed']) {
                this.openPopin();
                this.userIsPlaying.next(false);
                this.lockPlayBtn = false;
                this.cdRef.markForCheck();
              } else if (this.gameResult === InstantGameState.Pending) {
                this.updateMusikaInstantGameTransaction().subscribe(_ => {
                  this.updateBalance();
                });
              }
            }, 4000);
          },
          (err: BettingError) => {
            switch (err.failure) {
              case CreateBetFailures.TooManyRequests:
                this.messageService
                  .sendComponentMessage(GenericContentComponent, {
                    text: this.i18nService.translateSync('INSTANT-GAMES.ERRORS.TOO_MANY_REQUESTS')
                  })
                  .closed.subscribe(_ => {
                    this.cdRef.markForCheck();
                    this.lockPlayBtn = false;
                  });
                break;
              case CreateInstantGameTransactionFailure.CustomerLimitationExceeded:
              case CreateInstantGameTransactionFailure.CustomerSelfExcluded:
                this.messageService
                  .sendComponentMessage(
                    GenericContentComponent,
                    {
                      title: this.i18nService.translateSync('RESPONSIBLE_GAMBLING.SELF_LIMITATION'),
                      text: this.i18nService.translateSync('BET-SLIP.BETTING_ERROR.LIMIT_REACHED')
                    },
                    { canBeDismissed: true, displayClose: true, dark: true }
                  )
                  .closed.subscribe(_ => {
                    this.lockPlayBtn = false;
                    this.cdRef.markForCheck();
                  });
            }
          }
        );
    }
  }

  spin(params: { timer: number; reelRef: ElementRef; spinId: number }) {
    params.reelRef.nativeElement.style = '';
    (<HTMLElement>params.reelRef.nativeElement).className = 'ring';
    reanimate(params.reelRef.nativeElement, 'spin-' + params.spinId);
    params.reelRef.nativeElement.style = `animation: spin-${params.spinId} ${params.timer}s`;
  }

  updateBalance() {
    if (this.loggedIn) {
      this.authService.getBalance().subscribe(_ => {
        this.cdRef.markForCheck();
      });
    }
  }

  openPopin() {
    let popin;
    switch (this.gameResult) {
      case InstantGameState.Pending:
        popin = this.messageService.sendComponentMessage(
          MusikaPopinComponent,
          {
            transactionId: this.transactionId,
            wonInstrument: musikaInstruments[this.result[0] - 1],
            payableAmount: this.payableAmount,
            step: this.mode === InstantGameMode.Demo ? MusikaStatus.WonDemo : MusikaStatus.WonSpin,
            stake: this.currentStake
          },
          { canBeDismissed: false, displayClose: false, className: 'musika', id: 'musika' }
        );
        break;
      case InstantGameState.Lost:
        popin = this.messageService.sendComponentMessage(
          MusikaPopinComponent,
          { resultMain: this.result[0], amountMain: this.paidAmount, step: MusikaStatus.LostSpin },
          { canBeDismissed: true, displayClose: false, className: 'musika', id: 'musika' }
        );
        break;
    }

    if (this.mode === InstantGameMode.Real) {
      popin.closed.pipe(takeUntil(this.destroy$)).subscribe(() => {
        this.updateBalance();
      });
    }
  }

  updateMusikaInstantGameTransaction() {
    const selection = {};
    return this.bettingApiService.updateMusikaInstantGameTransaction({
      id: this.transactionId,
      instantGameName: InstantGameName.Musika,
      stake: this.currentStake,
      selection,
      instantGameMode: InstantGameMode.Real,
      doubleOrQuit: false
    });
  }

  updateCurrentStake(stake: number) {
    this.currentStake = stake;
    this.localStorageService.setItem(musikaLocalStorageKey, this.currentStake);
    this.gains = this.configuration.odds.map(x => x * this.currentStake);
  }
}
