import {
  Component,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  ElementRef,
  Inject,
  OnDestroy,
  Optional,
  ViewChild
} from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { BehaviorSubject, combineLatest, interval, Observable, of, Subject } from 'rxjs';
import {
  distinctUntilChanged,
  map,
  shareReplay,
  skip,
  startWith,
  switchMap,
  take,
  takeUntil,
  tap
} from 'rxjs/operators';
import { DialogService } from '@honoregaming/core';
import { GenericContentComponent, Media, MediaService, MessageService, ToasterService } from '@honoregaming/ui';
import { InstantGame } from '@honoregaming/types';
import { AuthService, authServiceToken } from '@honoregaming/authentication';
import { FavoriteManagerService } from 'projects/customer/hg-core/src/lib/services/domain/favorite-manager.service';
import {
  CountdownUnit,
  RankedMember,
  RewardCard,
  TournamentDetail,
  TournamentLeaderboard,
  TournamentPrize
} from '../../../types/tournament-detail.types';
import { I18nService } from 'projects/core/hg-i18n/src/lib/services/i18n.service';
import { computeCountdown } from '../../../utils/tournament.utils';
import { InstantGamesTournamentsService } from '../../../services/instant-games-tournaments.service';

type Tab = 'rewards' | 'ranking' | 'rules';

interface TournamentDetailViewModel {
  detail: TournamentDetail;
  leaderboard: TournamentLeaderboard;
  playerRank: RankedMember | null;
  isDesktop: boolean;
  isAuthenticated: boolean;
  isOngoing: boolean;
  isUpcoming: boolean;
  isEnded: boolean;
  hasLeaderboard: boolean;
  podiumOrder: (RankedMember | undefined)[];
  rewardCards: RewardCard[];
}

@Component({
  selector: 'hg-instant-games-tournament-detail',
  templateUrl: './instant-games-tournament-detail.component.html',
  styleUrls: ['./instant-games-tournament-detail.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class InstantGamesTournamentDetailComponent implements OnDestroy {
  activeTab: Tab = 'rules';
  arrowLeftVisible: boolean = false;
  arrowRightVisible: boolean = false;
  isOptInPending: boolean = false;

  private optInSuccessMsg: string = '';

  private isDragging: boolean = false;
  private dragStartX: number = 0;
  private dragScrollLeft: number = 0;
  hasDragged: boolean = false;

  @ViewChild('gamesScroll') private gamesScroll?: ElementRef<HTMLElement>;

  private readonly refreshSubject$ = new BehaviorSubject<void>(undefined);
  private readonly destroy$ = new Subject<void>();

  readonly vm$: Observable<TournamentDetailViewModel> = this.route.params.pipe(
    switchMap(({ id }) =>
      this.refreshSubject$.pipe(
        switchMap(() =>
          combineLatest([
            this.tournamentsService.getTournamentDetail(id as string),
            this.tournamentsService.getTournamentLeaderboard(id as string),
            this.mediaService ? this.mediaService.media$.pipe(map(media => media >= Media.lg)) : of(false),
            this.favoriteManagerService.favorites$.pipe(map(favs => new Set(favs.map(game => game.id)))),
            this.authService.status$.pipe(
              startWith(null),
              map(() => this.authService.isAuthenticated()),
              distinctUntilChanged()
            )
          ])
        )
      )
    ),
    map(([detail, leaderboard, isDesktop, favoriteIds, isAuthenticated]): TournamentDetailViewModel => {
      const members: RankedMember[] = leaderboard.playerAndAdjacentRankedMembers;
      const playerRank: RankedMember | null = detail.customerRanking
        ? members?.find(member => member.position === detail.customerRanking) ??
          leaderboard.topRankedMembers?.find(member => member.position === detail.customerRanking) ??
          leaderboard.bottomRankedMembers?.find(member => member.position === detail.customerRanking) ?? {
            position: detail.customerRanking,
            score: detail.customerScore ?? 0,
            isMe: true,
            login: '',
            cashPrizeAmount: 0,
            freeSpinPrizeCount: 0
          }
        : null;
      const enrichedDetail: TournamentDetail = {
        ...detail,
        instantGames: detail.instantGames?.map(game => ({ ...game, isFavorite: favoriteIds.has(game.id) })) ?? []
      };
      const now: number = Date.now();
      const startTime: number = new Date(detail.startDate).getTime();
      const endTime: number = new Date(detail.endDate).getTime();
      return {
        detail: enrichedDetail,
        leaderboard,
        playerRank,
        isDesktop,
        isAuthenticated,
        isOngoing: !detail.isFinished && now >= startTime,
        isUpcoming: !detail.isFinished && now < startTime,
        isEnded: now >= endTime,
        hasLeaderboard: leaderboard.topRankedMembers.some(member => member.score > 0),
        podiumOrder: [2, 1, 3].map(pos => leaderboard.topRankedMembers.find(member => member.position === pos)),
        rewardCards: this.groupPrizesByPosition(detail.prizes ?? [])
      };
    }),
    tap(vm => {
      if (!vm.detail.rules && this.activeTab === 'rules') {
        this.activeTab = vm.hasLeaderboard ? 'ranking' : 'rewards';
      }
      requestAnimationFrame(() => this.updateArrowVisibility());
    }),
    shareReplay(1)
  );

  readonly countdown$: Observable<CountdownUnit[]> = this.vm$.pipe(
    distinctUntilChanged((a, b) => a.detail.endDate === b.detail.endDate),
    switchMap(({ detail }) =>
      interval(1000).pipe(
        startWith(0),
        map(() => computeCountdown(detail.endDate))
      )
    )
  );

  constructor(
    private readonly route: ActivatedRoute,
    private readonly tournamentsService: InstantGamesTournamentsService,
    private readonly cdRef: ChangeDetectorRef,
    public readonly favoriteManagerService: FavoriteManagerService,
    private readonly toasterService: ToasterService,
    private readonly i18nService: I18nService,
    private readonly dialogService: DialogService,
    private readonly messageService: MessageService,
    @Inject(authServiceToken) private readonly authService: AuthService,
    @Optional() private readonly mediaService: MediaService
  ) {
    this.i18nService
      .translate('INSTANT-GAMES.TOURNAMENTS.OPTIN_SUCCESS')
      .pipe(take(1))
      .subscribe(msg => (this.optInSuccessMsg = msg));
    this.tournamentsService.tournaments$
      .pipe(skip(1), takeUntil(this.destroy$))
      .subscribe(() => this.refreshSubject$.next());
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }

  setTab(tab: Tab): void {
    this.activeTab = tab;
  }

  toggleFavorite(game: InstantGame, event: Event): void {
    event.stopPropagation();
    event.preventDefault();
    this.favoriteManagerService.toggle(game).pipe(take(1)).subscribe();
  }

  optIn(id: number): void {
    if (!this.authService.isAuthenticated()) {
      if (this.mediaService?.media >= Media.lg) {
        this.messageService
          .sendComponentMessage(
            GenericContentComponent,
            {
              title: this.i18nService.translateSync('COMMON.LOGIN_REQUIRED'),
              text: this.i18nService.translateSync('INSTANT-GAMES.TOURNAMENTS.LOGIN_REQUIRED'),
              okButton: true,
              okButtonTranslationKey: 'COMMON.I_GET_IT'
            } as any,
            { canBeDismissed: true, displayClose: true }
          )
          .closed.pipe(takeUntil(this.destroy$))
          .subscribe(confirmed => {
            if (confirmed) {
              this.dialogService.toggleDialog('login', true);
            }
          });
      } else {
        this.dialogService.toggleDialog('login', true);
      }
      return;
    }
    this.isOptInPending = true;
    this.cdRef.markForCheck();
    this.tournamentsService
      .optIn(id.toString())
      .pipe(take(1))
      .subscribe({
        next: () => {
          this.toasterService.show({ text: this.optInSuccessMsg, type: 'add', id: 'Tournament_OptIn_Notif' });
          this.refreshSubject$.next();
        },
        error: () => {
          this.isOptInPending = false;
          this.cdRef.markForCheck();
        }
      });
  }

  trackByPosition(_index: number, member: RankedMember): number {
    return member.position;
  }

  trackByGame(_index: number, game: InstantGame): number {
    return game.id;
  }

  trackByCard(_index: number, card: RewardCard): number {
    return card.fromPosition;
  }

  private groupPrizesByPosition(prizes: TournamentPrize[]): RewardCard[] {
    const cardMap = new Map<string, RewardCard>();
    for (const prize of prizes) {
      const key: string = `${prize.fromPosition}-${prize.toPosition}`;
      if (!cardMap.has(key)) {
        cardMap.set(key, {
          fromPosition: prize.fromPosition,
          toPosition: prize.toPosition,
          cashPrize: null,
          freeSpinPrize: null
        });
      }
      const card: RewardCard = cardMap.get(key)!;
      if (prize.rewardType === 'Cash') {
        card.cashPrize = prize;
      } else if (prize.rewardType === 'FreeSpin') {
        card.freeSpinPrize = prize;
      }
    }
    return Array.from(cardMap.values());
  }

  updateArrowVisibility(): void {
    const el: HTMLElement | undefined = this.gamesScroll?.nativeElement;
    if (!el) {
      return;
    }
    this.arrowLeftVisible = el.scrollLeft > 0;
    this.arrowRightVisible = el.scrollLeft + el.clientWidth < el.scrollWidth - 1;
    this.cdRef.detectChanges();
  }

  scrollGames(dir: 1 | -1): void {
    const el: HTMLElement | undefined = this.gamesScroll?.nativeElement;
    if (!el) {
      return;
    }
    el.scrollTo({ left: el.scrollLeft + dir * 500, behavior: 'smooth' });
    setTimeout(() => this.updateArrowVisibility(), 500);
  }

  startDragging(event: MouseEvent): void {
    const el: HTMLElement | undefined = this.gamesScroll?.nativeElement;
    if (!el) {
      return;
    }
    this.isDragging = true;
    this.hasDragged = false;
    this.dragStartX = event.pageX - el.offsetLeft;
    this.dragScrollLeft = el.scrollLeft;
  }

  stopDragging(): void {
    this.isDragging = false;
  }

  onMouseMove(event: MouseEvent): void {
    if (!this.isDragging) {
      return;
    }
    const el: HTMLElement | undefined = this.gamesScroll?.nativeElement;
    if (!el) {
      return;
    }
    const x: number = event.pageX - el.offsetLeft;
    const delta: number = x - this.dragStartX;
    if (Math.abs(delta) > 5) {
      this.hasDragged = true;
      event.preventDefault();
      el.scrollLeft = this.dragScrollLeft - delta;
      this.updateArrowVisibility();
    }
  }
}
