import {
  Component,
  ChangeDetectionStrategy,
  QueryList,
  ViewChildren,
  ElementRef,
  Input,
  AfterViewInit,
  OnChanges,
  Output,
  EventEmitter
} from '@angular/core';
import { Router } from '@angular/router';
import { InstantGame } from '@honoregaming/types';

@Component({
  selector: 'hg-instant-game-carousel',
  templateUrl: './instant-game-carousel.component.html',
  styleUrls: ['./instant-game-carousel.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class InstantGameCarouselComponent implements OnChanges, AfterViewInit {
  @Input() games: (InstantGame & { computedUrl: string })[];

  @Output() favoriteToggled = new EventEmitter<{ game: InstantGame; event: Event }>();

  @ViewChildren('slideElements')
  slideRefs: QueryList<ElementRef<HTMLElement>>;

  currentIndex = 0;

  slides: { type: string; inputs: any }[];

  swipeCoord: [number, number];
  swipeTime: number;
  timerInterval: any;
  swipeDirection: 'left' | 'right' | null = null;

  mouseMove = false;
  swipingStart: boolean = false;
  swipingMove: boolean = false;
  swipingEnd: boolean = false;

  constructor(public router: Router) {}

  ngOnChanges(): void {
    if (this.games.length !== 1 && this.games.length < 5) {
      this.games = this.duplicateArrayToMin5Items(this.games);
    }
  }

  ngAfterViewInit() {
    this.initPreviousNext();
  }

  redirect(url: string) {
    if (!this.mouseMove) {
      this.router.navigate([url]);
    }

    this.mouseMove = false;
  }

  initPreviousNext() {
    const sliderArray = this.slideRefs.toArray();
    this.addClassesWithoutTransition(
      sliderArray[(this.currentIndex + sliderArray.length - 1) % sliderArray.length]?.nativeElement,
      'prev'
    );
    this.addClassesWithoutTransition(
      sliderArray[(this.currentIndex + sliderArray.length + 1) % sliderArray.length]?.nativeElement,
      'next'
    );
    this.addClassesWithoutTransition(
      sliderArray[(this.currentIndex + sliderArray.length + 2) % sliderArray.length]?.nativeElement,
      'next-next'
    );
    this.addClassesWithoutTransition(
      sliderArray[(this.currentIndex + sliderArray.length - 2) % sliderArray.length]?.nativeElement,
      'prev-prev'
    );
  }

  initialPositions = {
    active: 0,
    next: 0,
    'next-next': 0,
    prev: 0,
    'prev-prev': 0
  };

  initialSlideWidth = 0;

  swipe(e: TouchEvent, event: 'start' | 'move' | 'end'): void {
    if (this.games.length <= 1) return;

    const classes = ['next', 'prev', 'active', 'next-next', 'prev-prev'];
    const [x, y] = [e.changedTouches[0].pageX, e.changedTouches[0].pageY];
    const time = Date.now();

    switch (event) {
      case 'start':
        this.handleSwipeStart(x, y, time, classes);
        break;
      case 'move':
        this.handleSwipeMove(x, classes);
        break;
      case 'end':
        this.handleSwipeEnd(x, y, time, classes);
        break;
    }
  }

  private handleSwipeStart(x: number, y: number, time: number, classes: string[]): void {
    if (!this.swipingStart) {
      this.swipingStart = true;
      this.swipeCoord = [x, y];
      this.swipeTime = time;
      this.initialSlideWidth = this.getElementByClass('active').getBoundingClientRect().width;

      classes.forEach(cls => {
        const el = this.getElementByClass(cls);
        const transform = getComputedStyle(el).transform;
        this.initialPositions[cls] = new DOMMatrixReadOnly(transform).m41;
      });

      this.applyToSlides(classes, el => el.classList.add('notransition'));
    }
  }

  private handleSwipeMove(x: number, classes: string[]): void {
    if (!this.swipingMove) {
      this.swipingMove = true;
      const distX = Math.round(
        Math.max(-this.initialSlideWidth, Math.min(this.initialSlideWidth, x - this.swipeCoord[0])) / 6
      );

      classes.forEach(cls => {
        const el = this.getElementByClass(cls);
        el.style.transform = `translate(${this.initialPositions[cls] + distX}px, -50%)`;
      });
    }
  }

  private handleSwipeEnd(x: number, y: number, time: number, classes: string[]): void {
    if (!this.swipingEnd) {
      this.swipingEnd = true;
      const [dx, dy] = [x - this.swipeCoord[0], y - this.swipeCoord[1]];
      const duration = time - this.swipeTime;
      const isSwipeValid = duration > 100 && Math.abs(dx) > 30 && Math.abs(dx) > Math.abs(dy * 3);

      if (isSwipeValid) {
        let nextIndex: number;

        if (dx > 0) {
          nextIndex = this.currentIndex === 0 ? this.games.length - 1 : this.currentIndex - 1;
        } else {
          nextIndex = (this.currentIndex + 1) % this.games.length;
        }

        this.navTo(nextIndex, dx > 0);

        setTimeout(() => {
          this.applyToSlides(classes, el => (el.style.transform = ''));
        }, 30);
      } else {
        this.applyToSlides(classes, el => {
          el.classList.remove('notransition');
          el.style.transform = '';
        });
      }

      setTimeout(() => {
        this.swipingStart = false;
        this.swipingMove = false;
        this.swipingEnd = false;
      }, 200);
    }
  }

  private applyToSlides(classes: string[], callback: (el: HTMLElement) => void): void {
    this.slideRefs
      .filter(ref => classes.some(cls => ref.nativeElement.classList.contains(cls)))
      .forEach(ref => callback(ref.nativeElement));
  }

  getElementByClass = (className: string): HTMLElement =>
    this.slideRefs.filter(x => x.nativeElement.classList.contains(className))?.[0]?.nativeElement;

  navTo(index: number, back = false) {
    if (this.currentIndex === index) {
      return;
    }

    const prevClass = back ? 'next' : 'prev';
    const nextClass = back ? 'prev' : 'next';
    const classes = ['next', 'prev', 'next-next', 'prev-prev'];

    const sliderArray = this.slideRefs.toArray();
    const next = sliderArray[index];

    if (
      [1, sliderArray.length - 1].indexOf((this.currentIndex - index + sliderArray.length) % sliderArray.length) > -1
    ) {
      setTimeout(() => {
        this.slideRefs.forEach(x => {
          if (x.nativeElement.classList.contains('next-next') && back) {
            x.nativeElement.classList.add('notransition');
          } else {
            x.nativeElement.classList.remove('notransition');
          }
          classes.forEach(c => x.nativeElement.classList.remove(c));
        });
        sliderArray[(index + sliderArray.length - 1) % sliderArray.length].nativeElement.classList.add('prev');
        sliderArray[(index + sliderArray.length + 1) % sliderArray.length].nativeElement.classList.add('next');
        sliderArray[(index + sliderArray.length - 2) % sliderArray.length].nativeElement.classList.add('prev-prev');
        sliderArray[(index + sliderArray.length + 2) % sliderArray.length].nativeElement.classList.add('next-next');
        if (!back) {
          sliderArray[(index + sliderArray.length + 2) % sliderArray.length].nativeElement.classList.add(
            'notransition'
          );
        } else {
          sliderArray[(index + sliderArray.length - 2) % sliderArray.length].nativeElement.classList.add(
            'notransition'
          );
        }
      });
    }

    setTimeout(() => {
      const cur = sliderArray[this.currentIndex];
      this.currentIndex = index;

      sliderArray.forEach(slide => slide.nativeElement.classList.remove('active'));
      next.nativeElement.classList.add('active');

      next.nativeElement.classList.remove(nextClass);
      cur.nativeElement.classList.add(prevClass);
    });
  }

  fakeScope = {};
  private addClassesWithoutTransition(element: HTMLElement, ...cssClasses: string[]) {
    if (element) {
      element.classList.add('notransition', 'zero-transition');
      element.classList.add(...cssClasses);
      this.fakeScope = element.offsetWidth;
      element.classList.remove('notransition');
      element.classList.remove('zero-transition');
    }
  }

  duplicateArrayToMin5Items = <T>(a: T[]): T[] => {
    const duplicated = Array.from({ length: 5 }, (_, i) => a[i % a.length]);
    const rotated = [...duplicated.slice(1), duplicated[0]];
    return rotated;
  };

  onToggleFavorited(game: InstantGame, event: Event) {
    event.stopPropagation();
    event.preventDefault();
    this.favoriteToggled.emit({ game, event });
    this.currentIndex = Math.min(this.currentIndex, this.games.length - 1);
  }

  trackByGame(_index: number, game: InstantGame) {
    return game.id;
  }
}
