import { ChangeDetectionStrategy, ChangeDetectorRef, Component, Inject, Input, OnChanges, OnInit } from '@angular/core';
import { globalConfiguration, OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { InstantGameService } from '@honoregaming/events';
import { InstantGame, InstantGameProvider } from '@honoregaming/types';
import { ActivatedRoute, Router } from '@angular/router';
import { finalize, map, switchMap, takeUntil } from 'rxjs/operators';
import { BetCategoryConfigurationService, DestroySubject } from '@honoregaming/core';

@Component({
  selector: 'hg-similar-games',
  templateUrl: './similar-games.component.html',
  styleUrls: ['./similar-games.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class SimilarGamesComponent extends DestroySubject implements OnInit, OnChanges {
  @Input() gameClicked: (gameName: string) => void;
  @Input() gameId: number;
  @Input() provider: string;
  public categoryId: number;
  public games: (InstantGame & { computedUrl: string })[];
  loading: boolean;

  baseAssetsPath = this.operatorConfiguration.instantGamesConfiguration.insaGamesAssetsPath;
  assetsPath: string = '';

  instantGamesBetCategoryPath = this.betCategoryConfigurationService.getInstantGamesBetCategoryPath();

  constructor(
    public instantGameService: InstantGameService,
    public betCategoryConfigurationService: BetCategoryConfigurationService,
    @Inject(operatorConfigurationToken) public operatorConfiguration: OperatorConfiguration,
    public router: Router,
    public cdRef: ChangeDetectorRef,
    public route: ActivatedRoute
  ) {
    super();
  }

  ngOnInit(): void {
    const regex = new RegExp(/^(https?:\/\/[^\/]+)/); // Permet de matcher l'url de base
    const matches = regex.exec(globalConfiguration.assetsPath);
    this.assetsPath = matches ? matches[0] : '';
  }

  ngOnChanges(): void {
    this.initializeComponent();
  }

  initializeComponent() {
    if (this.gameId && this.provider) {
      this.games = [];
      this.route.queryParams
        .pipe(
          takeUntil(this.destroy$),
          map(params => +params['categoryId']),
          switchMap(categoryId => {
            if (!categoryId || Number.isNaN(categoryId)) {
              categoryId = 0;
            }

            this.categoryId = categoryId;
            return this.instantGameService.getSimilarGames(this.gameId, categoryId);
          }),
          finalize(() => {
            this.loading = false;
            this.cdRef.markForCheck();
          })
        )
        .subscribe((gamesList: InstantGame[]) => {
          this.games = gamesList.map(g => this.mapGame(g));
          this.cdRef.markForCheck();
        });
    }
  }

  mapGame(game: InstantGame) {
    if (game.provider === 'InsaGames') {
      return {
        ...game,
        computedUrl: `/${this.instantGamesBetCategoryPath}/` + game.url,
        imageUrl: game.imageUrl || `${this.baseAssetsPath}${game.name.toLowerCase()}/thumbnail.png`
      };
    } else if (game.provider === InstantGameProvider.EveryMatrix) {
      return { ...game, computedUrl: `/${this.instantGamesBetCategoryPath}/` + game.url };
    } else if (game.provider === InstantGameProvider.GameTech) {
      return {
        ...game,
        computedUrl: `/${this.instantGamesBetCategoryPath}/` + game.url,
        imageUrl: !game.imageUrl.startsWith('http')
          ? `${this.assetsPath}/instant-game-providers/${game.imageUrl}`
          : game.imageUrl
      };
    } else if (game.provider === InstantGameProvider.AviatorLlc) {
      return {
        ...game,
        computedUrl: `/${this.instantGamesBetCategoryPath}/` + game.url
      };
    } else if (game.provider === InstantGameProvider.BoomingGames) {
      return {
        ...game,
        computedUrl: `/${this.instantGamesBetCategoryPath}/` + game.url,
        imageUrl: game.imageUrl
      };
    }

    return game;
  }

  goToInstantGamesHome() {
    this.router.navigate([this.betCategoryConfigurationService.getInstantGamesBetCategoryPath()]);
  }

  trackBy(_index: number, game: InstantGame) {
    return game.id;
  }
}
