import { Injectable } from '@angular/core';
import { map, tap } from 'rxjs/operators';
import { BehaviorSubject, Observable } from 'rxjs';
import { ToasterService } from '@honoregaming/ui';
import { InstantGame } from 'projects/core/hg-types/models/instant-games/instant-game.model';
import { I18nService } from 'projects/core/hg-i18n/src/lib/services/i18n.service';
import { FavoritesService } from '../favorites.service';

@Injectable({ providedIn: 'root' })
export class FavoriteManagerService {
  private readonly favoritesSubject = new BehaviorSubject<InstantGame[]>([]);
  favorites$: Observable<InstantGame[]> = this.favoritesSubject.asObservable();

  private addFavoriteMsg: string = '';
  private removeFavoriteMsg: string = '';

  constructor(
    private readonly favoritesService: FavoritesService,
    private readonly toaster: ToasterService,
    private readonly i18nService: I18nService
  ) {
    this.i18nService.translate('INSTANT_GAMES.FAVORITES.ADD').subscribe(message => (this.addFavoriteMsg = message));

    this.i18nService
      .translate('INSTANT_GAMES.FAVORITES.REMOVE')
      .subscribe(message => (this.removeFavoriteMsg = message));
  }

  loadFavorites(): Observable<InstantGame[]> {
    return this.favoritesService.getInstantGameFavorite().pipe(tap(favs => this.favoritesSubject.next(favs)));
  }

  updateFavorite(game: InstantGame): void {
    const current: InstantGame[] = this.favoritesSubject.value;
    const exists: boolean = current.some(instantGame => instantGame.id === game.id);

    const updated: InstantGame[] = exists
      ? current.filter(instantGame => instantGame.id !== game.id)
      : [{ ...game, isFavorite: true }, ...current];

    this.favoritesSubject.next(updated);
  }

  clearFavorites(): void {
    this.favoritesSubject.next([]);
  }

  toggle(game: InstantGame, options?: { undoContext?: boolean; undoAction?: () => void }): Observable<InstantGame> {
    const remove: boolean = game.isFavorite;
    const action: 'add' | 'remove' = remove ? 'remove' : 'add';
    const msg = remove ? this.removeFavoriteMsg : this.addFavoriteMsg;
    const text: string = `${game.name} ${msg}`;

    return this.favoritesService.updateInstantGameFavorite(game.id, remove).pipe(
      tap(() => {
        if (options?.undoContext && remove) {
          this.toaster.show({
            text,
            type: action,
            id: remove ? 'Casino_RemoveFromFav_Notif' : 'Casino_AddToFav_Notif',
            action: () => {
              options.undoAction?.();
            }
          });
          return;
        }
        this.toaster.show({ text, type: action, id: remove ? 'Casino_RemoveFromFav_Notif' : 'Casino_AddToFav_Notif' });
      }),
      map(() => {
        game.isFavorite = !remove;
        this.updateFavorite(game);
        return game;
      })
    );
  }
}
